import { FINGER_NAMES, fingeringBarres, suggestFingering, type ChordFingering } from '../chords/fingering';

/** Vertical chord-chart diagram (low E on the left, nut on top) shared by the library, the player and the chord game. */
export interface ChordBoxOptions {
  /** App string order: index 0 is the high e, 5 the low E; null is muted. */
  frets: readonly (number | null)[];
  /** Defaults to the suggested teaching fingering. */
  fingering?: ChordFingering | null;
  /** Finger numbers inside the dots; defaults to true. */
  numbers?: boolean;
  /** Per string (app order): true when that string sounds the chord root. */
  roots?: readonly boolean[];
  /** Left-handed charts put the low E on the right. */
  mirrored?: boolean;
  /** Accessible chord name, for example "G major". */
  name?: string;
  /** Labels under the strings in app order, for example tuning notes. */
  stringNames?: readonly string[];
  className?: string;
}

const LEFT = 26, GAP = 16, TOP = 30, ROW = 20, DOT = 7;
const RIGHT = LEFT + GAP * 5;
const WIDTH = RIGHT + 26;
const escapeXml = (text: string): string => text.replace(/[&<>"']/g, c => `&#${c.charCodeAt(0)};`);
const fixed = (value: number): string => String(Math.round(value * 10) / 10);

/** First fret drawn and number of rows; shapes that fit in five frets keep the nut. */
export function chordBoxWindow(frets: readonly (number | null)[]): { base: number; rows: number; nut: boolean } {
  const fretted = frets.filter((fret): fret is number => fret !== null && fret > 0);
  if (!fretted.length) return { base: 1, rows: 4, nut: true };
  const high = Math.max(...fretted), low = Math.min(...fretted);
  if (high <= 5) return { base: 1, rows: Math.max(4, high), nut: true };
  return { base: low, rows: Math.max(4, high - low + 1), nut: false };
}

function describe(frets: readonly (number | null)[], fingering: ChordFingering, names?: readonly string[]): string {
  const parts: string[] = [];
  for (let s = frets.length - 1; s >= 0; s--) {
    const fret = frets[s];
    const label = names?.[s] ? `string ${s + 1} (${names[s]})` : `string ${s + 1}`;
    if (fret === null) parts.push(`${label} muted`);
    else if (fret === 0) parts.push(`${label} open`);
    else {
      const finger = fingering.fingers[s];
      parts.push(finger ? `${label} fret ${fret}, ${FINGER_NAMES[finger as 1 | 2 | 3 | 4]} finger (${finger})` : `${label} fret ${fret}`);
    }
  }
  const barres = fingeringBarres(frets, fingering);
  return `${parts.join('; ')}.${barres.map(barre => ` ${FINGER_NAMES[barre.finger]} finger barres fret ${barre.fret} from string ${barre.toString + 1} to string ${barre.fromString + 1}.`).join('')}`;
}

export function chordBoxSvg(options: ChordBoxOptions): string {
  const frets = options.frets;
  const fingering = options.fingering ?? suggestFingering(frets);
  const numbers = options.numbers !== false;
  const { base, rows, nut } = chordBoxWindow(frets);
  const bottom = TOP + rows * ROW;
  const height = bottom + (options.stringNames ? 22 : 10);
  const x = (s: number): number => LEFT + GAP * (options.mirrored ? s : 5 - s);
  const rowY = (fret: number): number => TOP + (fret - base + 0.5) * ROW;
  const parts: string[] = [];

  for (let r = nut ? 1 : 0; r <= rows; r++) {
    parts.push(`<line class="cb-fret" x1="${LEFT}" x2="${RIGHT}" y1="${TOP + r * ROW}" y2="${TOP + r * ROW}" stroke="#6f7468" stroke-width="1.2"/>`);
  }
  for (let s = 0; s < 6; s++) {
    parts.push(`<line class="cb-string" x1="${x(s)}" x2="${x(s)}" y1="${TOP}" y2="${bottom}" stroke="#c9c1ae" stroke-width="${fixed(0.9 + s * 0.16)}"/>`);
  }
  if (nut) parts.push(`<rect class="cb-nut" x="${LEFT - 1.5}" y="${TOP - 3}" width="${RIGHT - LEFT + 3}" height="5" rx="1.5" fill="#f0dfc6"/>`);
  else {
    const side = options.mirrored ? RIGHT + 8 : LEFT - 8;
    parts.push(`<text class="cb-base" x="${side}" y="${fixed(rowY(base))}" text-anchor="${options.mirrored ? 'start' : 'end'}" dominant-baseline="central" font-size="9" fill="#a9afa9">${base}fr</text>`);
  }

  frets.forEach((fret, s) => {
    const cx = x(s), cy = TOP - 11;
    if (fret === null) {
      parts.push(`<path class="cb-mark cb-muted" d="M${cx - 3.5} ${cy - 3.5}L${cx + 3.5} ${cy + 3.5}M${cx + 3.5} ${cy - 3.5}L${cx - 3.5} ${cy + 3.5}" stroke="#a9afa9" stroke-width="1.4" stroke-linecap="round" fill="none"/>`);
    } else if (fret === 0) {
      const root = options.roots?.[s];
      parts.push(`<circle class="cb-mark cb-open${root ? ' cb-root' : ''}" cx="${cx}" cy="${cy}" r="3.8" stroke="${root ? '#eabb7f' : '#c9c1ae'}" stroke-width="1.4" fill="none"/>`);
    }
  });

  const covered = new Set<number>();
  for (const barre of fingeringBarres(frets, fingering)) {
    const own = new Set<number>();
    for (let s = barre.fromString; s <= barre.toString; s++) {
      if (frets[s] === barre.fret && fingering.fingers[s] === barre.finger) { covered.add(s); own.add(s); }
    }
    const ends = [x(barre.fromString), x(barre.toString)];
    const from = Math.min(...ends) - DOT, to = Math.max(...ends) + DOT, cy = rowY(barre.fret);
    const root = [...own].some(s => options.roots?.[s]);
    parts.push(`<rect class="cb-dot cb-barre${root ? ' cb-root' : ''}" x="${fixed(from)}" y="${fixed(cy - DOT)}" width="${fixed(to - from)}" height="${DOT * 2}" rx="${DOT}" fill="${root ? '#eabb7f' : '#f0dfc6'}"/>`);
    if (numbers) parts.push(`<text class="cb-num" x="${fixed((from + to) / 2)}" y="${fixed(cy)}" text-anchor="middle" dominant-baseline="central" font-size="9.5" font-weight="700" fill="#1f1b15">${barre.finger}</text>`);
  }

  frets.forEach((fret, s) => {
    if (fret === null || fret === 0 || covered.has(s)) return;
    const cx = x(s), cy = rowY(fret), root = options.roots?.[s];
    parts.push(`<circle class="cb-dot${root ? ' cb-root' : ''}" cx="${cx}" cy="${fixed(cy)}" r="${DOT}" fill="${root ? '#eabb7f' : '#f0dfc6'}"/>`);
    const finger = fingering.fingers[s];
    if (numbers && finger) parts.push(`<text class="cb-num" x="${cx}" y="${fixed(cy)}" text-anchor="middle" dominant-baseline="central" font-size="9.5" font-weight="700" fill="#1f1b15">${finger}</text>`);
  });

  if (options.stringNames) {
    options.stringNames.forEach((label, s) => {
      parts.push(`<text class="cb-name" x="${x(s)}" y="${bottom + 13}" text-anchor="middle" font-size="8" fill="#a9afa9">${escapeXml(label)}</text>`);
    });
  }

  const label = `${options.name ? `${options.name} chord diagram` : 'Chord diagram'}${options.mirrored ? ', left-handed' : ''}: ${describe(frets, fingering, options.stringNames)}`;
  const className = ['chord-box', options.className].filter(Boolean).join(' ');
  return `<svg class="${escapeXml(className)}" viewBox="0 0 ${WIDTH} ${height}" role="img" aria-label="${escapeXml(label)}" xmlns="http://www.w3.org/2000/svg">${parts.join('')}</svg>`;
}
