import { CHORD_FORMULAS } from './definitions';
import { PITCH_CLASSES } from '../songs/timing';
import { NOTE_NAMES, type ChordQuality } from '../types';

const LETTERS = ['C', 'D', 'E', 'F', 'G', 'A', 'B'];
const LETTER_PCS = [0, 2, 4, 5, 7, 9, 11];
const LETTER_OFFSETS: Record<number, number> = { 0: 0, 1: 1, 2: 1, 3: 2, 4: 2, 5: 3, 6: 4, 7: 4, 8: 4, 9: 5, 10: 6, 11: 6 };
const FLAT_NAMES = ['C', 'Db', 'D', 'Eb', 'E', 'F', 'Gb', 'G', 'Ab', 'A', 'Bb', 'B'];

/** Spell a chord tone from its degree (C7 → B♭, A → C♯); double accidentals fall back to a plain enharmonic. */
export function spellChordTone(rootText: string, quality: ChordQuality, pitchClass: number): string {
  const rootPc = PITCH_CLASSES[rootText];
  const pc = ((pitchClass % 12) + 12) % 12;
  const interval = (pc - rootPc + 12) % 12;
  const flats = rootText.includes('b') || rootText === 'F';
  if (rootPc === undefined || !CHORD_FORMULAS[quality]?.some(step => step % 12 === interval)) return (flats ? FLAT_NAMES : NOTE_NAMES)[pc];
  const offset = interval === 9 && quality === 'dim7' ? 6 : LETTER_OFFSETS[interval];
  const letter = (LETTERS.indexOf(rootText[0]) + offset) % 7;
  let difference = (pc - LETTER_PCS[letter] + 12) % 12;
  if (difference > 6) difference -= 12;
  if (difference === 0) return LETTERS[letter];
  if (difference === 1) return `${LETTERS[letter]}#`;
  if (difference === -1) return `${LETTERS[letter]}b`;
  return (flats ? FLAT_NAMES : NOTE_NAMES)[pc];
}
