/**
 * Suggested fretting-hand finger numbers for a chord shape.
 *
 * Frets use the app's string order: index 0 is the high e string, index 5 the low E string.
 * Finger numbers follow the usual chord-chart convention: 1 index, 2 middle, 3 ring, 4 little,
 * 0 open and null muted. These are teaching suggestions; other comfortable fingerings exist.
 */
export type FingerNumber = 0 | 1 | 2 | 3 | 4;

export interface FingerBarre {
  fret: number;
  /** Lowest app string index covered (nearest the high e). */
  fromString: number;
  /** Highest app string index covered (nearest the low E). */
  toString: number;
}

export interface ChordFingering {
  fingers: (FingerNumber | null)[];
  barre: FingerBarre | null;
}

export interface NumberedBarre extends FingerBarre { finger: 1 | 2 | 3 | 4 }

/** Every repeated finger is one physical barre, including middle/ring-finger mini barres. */
export function fingeringBarres(frets: readonly (number | null)[], fingering: ChordFingering): NumberedBarre[] {
  const barres: NumberedBarre[] = [];
  for (const finger of [1, 2, 3, 4] as const) {
    const strings = frets.flatMap((fret, s) => fret !== null && fret > 0 && fingering.fingers[s] === finger ? [s] : []);
    if (strings.length < 2) continue;
    const fromString = Math.min(...strings), toString = Math.max(...strings), fret = frets[fromString]!;
    if (strings.some(s => frets[s] !== fret) || frets.slice(fromString, toString + 1).some(f => f !== null && f < fret)) {
      throw new Error('One finger cannot press different frets or barre across an open string.');
    }
    barres.push({ finger, fret, fromString, toString });
  }
  return barres;
}

function groupedFingering(low: readonly (number | null)[]): ChordFingering {
  const notes = low.flatMap((fret, string) => fret !== null && fret > 0 ? [{ fret, string }] : []);
  const stretch = Math.max(...notes.map(note => note.fret)) - Math.min(...notes.map(note => note.fret));
  // Compact mini barres keep the longer middle/ring fingers available for a wide reach.
  const fingerCost = stretch >= 3 ? 1.5 : 0;
  const groups: { fret: number; strings: number[]; mask: number; cost: number }[] = [];
  for (const a of notes) for (const b of notes) {
    if (b.string < a.string || b.fret !== a.fret || low.slice(a.string, b.string + 1).some(fret => fret !== null && fret < a.fret)) continue;
    const strings = notes.filter(note => note.fret === a.fret && note.string >= a.string && note.string <= b.string).map(note => note.string);
    groups.push({ fret: a.fret, strings, mask: strings.reduce((mask, s) => mask | 1 << s, 0),
      cost: fingerCost + (strings.length > 1 ? 1 + (b.string - a.string) * .2 : 0) });
  }
  const required = notes.reduce((mask, note) => mask | 1 << note.string, 0);
  let best: typeof groups | null = null, bestCost = Infinity;
  const search = (mask: number, selected: typeof groups, cost: number): void => {
    if (cost >= bestCost) return;
    if (mask === required) { best = selected; bestCost = cost; return; }
    if (selected.length === 4) return;
    const string = notes.find(note => !(mask & 1 << note.string))!.string;
    for (const group of groups) if ((group.mask & 1 << string) && !(mask & group.mask)) {
      search(mask | group.mask, [...selected, group], cost + group.cost);
    }
  };
  search(0, [], 0);
  if (!best) throw new Error('This shape needs more than four fretting fingers.');
  const ordered = (best as typeof groups).sort((a, b) => a.fret - b.fret || a.strings[0] - b.strings[0]);
  const fingers: (FingerNumber | null)[] = low.map(fret => fret === null ? null : 0);
  ordered.forEach((group, i) => group.strings.forEach(s => { fingers[s] = (i + 1) as FingerNumber; }));
  const result: ChordFingering = { fingers: fingers.reverse(), barre: null };
  const index = fingeringBarres([...low].reverse(), result).find(barre => barre.finger === 1);
  if (index) result.barre = { fret: index.fret, fromString: index.fromString, toString: index.toString };
  return result;
}

/** Shapes whose conventional teaching fingering differs from the generic rule (low E → high e). */
const CONVENTIONAL: Record<string, readonly (FingerNumber | null)[]> = {
  '022000': [0, 2, 3, 0, 0, 0], // Em: middle and ring keep the index free for E-family changes.
  'x32000': [null, 3, 2, 0, 0, 0], // Cmaj7 keeps the C-chord hand position.
  'x02020': [null, 0, 2, 0, 3, 0], // A7
  '022200': [0, 2, 3, 4, 0, 0], // Esus4 adds the little finger to the E shape.
};

const shapeKey = (low: readonly (number | null)[]) => low.map(f => f === null ? 'x' : String(f)).join('');

/** Suggest finger numbers and an index-finger barre for a six-string shape. */
export function suggestFingering(frets: readonly (number | null)[]): ChordFingering {
  if (frets.length !== 6) throw new Error('Finger suggestions need six strings.');
  // Reason from low E to high e, as guitarists read chord shapes.
  const low = [...frets].reverse().map(f => (f === null || f === undefined || !Number.isFinite(f) || f < 0 ? null : Math.round(f)));
  const toApp = (lowFingers: readonly (FingerNumber | null)[]) => [...lowFingers].reverse() as (FingerNumber | null)[];
  const conventional = CONVENTIONAL[shapeKey(low)];
  if (conventional) return { fingers: toApp(conventional), barre: null };

  const fretted = low.flatMap((fret, string) => (fret !== null && fret > 0 ? [{ string, fret }] : []));
  const fingers: (FingerNumber | null)[] = low.map(fret => (fret === null ? null : 0));
  if (!fretted.length) return { fingers: toApp(fingers), barre: null };

  const minFret = Math.min(...fretted.map(note => note.fret));
  const atMin = fretted.filter(note => note.fret === minFret).map(note => note.string);
  const first = Math.min(...atMin), last = Math.max(...atMin);
  const span = low.slice(first, last + 1);
  // Full barre: five or six fretted strings with every string under the index at or above its fret.
  const fullBarre = fretted.length > 4 && atMin.length >= 2 && span.every(fret => fret !== null && fret >= minFret);
  // Partial barre: a run of two or more strings at the lowest fret that ends on the high e string.
  const partialBarre = !fullBarre && atMin.length >= 2 && last === 5
    && span.every(fret => fret === minFret);
  const barreStrings = fullBarre || partialBarre ? new Set(atMin) : null;
  if (!barreStrings && fretted.length >= 4 && atMin.length >= 3 && Math.max(...fretted.map(note => note.fret)) - minFret >= 3) {
    return groupedFingering(low);
  }

  const assign = (sequential: boolean): boolean => {
    const used = new Set<number>(barreStrings ? [1] : []);
    const ordered = fretted
      .filter(note => !barreStrings?.has(note.string))
      .sort((a, b) => a.fret - b.fret || a.string - b.string);
    let next = barreStrings ? 2 : 1;
    for (const note of ordered) {
      let finger: number;
      if (sequential) finger = next++;
      else {
        finger = Math.max(barreStrings ? 2 : 1, 1 + note.fret - minFret);
        while (used.has(finger)) finger++;
      }
      if (finger > 4) return false;
      used.add(finger);
      fingers[note.string] = finger as FingerNumber;
    }
    barreStrings?.forEach(string => { fingers[string] = 1; });
    return true;
  };
  if (!assign(false) && !assign(true)) {
    return groupedFingering(low);
  }

  const barre = barreStrings
    ? { fret: minFret, fromString: 5 - last, toString: 5 - first }
    : null;
  return { fingers: toApp(fingers), barre };
}

/** Compact text for cards and screen readers, low E → high e (for example "x 3 2 0 1 0"). */
export function fingeringText(fingering: ChordFingering): string {
  return [...fingering.fingers].reverse().map(f => (f === null ? 'x' : String(f))).join(' ');
}

export const FINGER_NAMES: Readonly<Record<1 | 2 | 3 | 4, string>> = { 1: 'index', 2: 'middle', 3: 'ring', 4: 'little' };
