function tabla(stem: string, sounds: readonly [number, string][], creator = 'mmiron', userId = 1565498,
  license: 'CC0-1.0' | 'CC-BY-4.0' = 'CC0-1.0'): PercussionSampleAsset[] {
  return sounds.map(([id, title]) => ({
    path: `freesound/tabla-${stem}-${id}.mp3`,
    url: `https://cdn.freesound.org/previews/${Math.floor(id / 1000)}/${id}_${userId}-hq.mp3`,
    velocity: 1, source: 'Freesound', calibrate: true,
    attribution: { title, creator, page: `https://freesound.org/people/${creator}/sounds/${id}/`, license },
  }));
}
