import { RHYTHM_PRESETS } from '../tabs/rhythm';
import { GROOVE_LANES, TABLA_LANES, getDrumGroove, type DrumGroove, type GrooveLane, type GrooveLanes } from './drumGrooves';
import { ENSEMBLE_LAYERS, type EnsembleLayer, type PercussionLayerLevel } from './percussion';

export const ENSEMBLE_INSTRUMENTS = {
  drums: 'Drums', tabla: 'Tabla', conga: 'Congas', bongos: 'Bongos', cajon: 'Cajón',
} as const;
export type EnsembleInstrument = keyof typeof ENSEMBLE_INSTRUMENTS;
export type EnsembleChoice = EnsembleInstrument | 'off';
export interface EnsembleSlot extends PercussionLayerLevel { instrument: EnsembleChoice }
export interface EnsemblePart {
  readonly layer: EnsembleLayer;
  readonly instrument: EnsembleInstrument;
  readonly pattern: string;
  readonly lanes: readonly GrooveLane[];
  readonly seed: number;
}
export interface GrooveEnsemble { readonly parts: readonly EnsemblePart[]; readonly drumId: string | null }

const HAND_LANES: Record<Exclude<EnsembleInstrument, 'drums'>, readonly GrooveLane[]> = {
  tabla: TABLA_LANES, conga: ['congaSlap', 'congaOpen', 'congaLow'],
  bongos: ['bongoHigh', 'bongoLow'], cajon: ['cajonBass', 'cajonSnare'],
};
const TOUCH_SEEDS: Record<EnsembleInstrument, number> = {
  drums: 0, tabla: 0x7461626c, conga: 0x636f6e67, bongos: 0x626f6e67, cajon: 0x63616a6f,
};

export function defaultEnsembleSlots(): EnsembleSlot[] {
  return ENSEMBLE_LAYERS.map((_, index) => ({ instrument: index === 0 ? 'drums' : index === 1 ? 'tabla' : 'off', level: .8, muted: false }));
}

export function isEnsembleChoice(value: string): value is EnsembleChoice {
  return value === 'off' || Object.hasOwn(ENSEMBLE_INSTRUMENTS, value);
}

export function ensemblePattern(instrument: EnsembleChoice, drum: DrumGroove): string {
  switch (instrument) {
    case 'drums': return drum.name;
    case 'tabla': return 'Keharwa · 8 bols per bar';
    case 'conga': return 'Conga conversation · 8 pulses per bar';
    case 'bongos': return 'Bongo exchange · 8 pulses per bar';
    case 'cajon': return 'Cajón groove · bass & slap';
    default: return 'No sound in this slot';
  }
}

export function ensembleDrumProblem(drum: DrumGroove): string | null {
  if (drum.loop) return 'Ensembles use built-in patterns, not imported loops.';
  if (drum.meter !== '4/4' || drum.beatsPerBar !== 4) return `${drum.name} is ${drum.meter}. The ensemble needs a 4/4 drum groove; other meters remain available solo.`;
  if (drum.stepsPerBeat !== 4 || drum.stepsPerBar !== 16) return 'Triplet-grid grooves remain solo. Choose a straight-grid 4/4 drum groove for the ensemble.';
  const handLanes = Object.values(HAND_LANES).flat();
  if (!drum.kitGroove || drum.ensemble || [drum.main, drum.chorus, drum.fill].some(lanes => Object.keys(lanes).some(lane => handLanes.includes(lane as GrooveLane)))) {
    return 'Choose a drum-kit groove here. Select tabla, congas, bongos or cajón in their own ensemble slots.';
  }
  return null;
}

export function ensembleProblem(slots: readonly EnsembleSlot[], drum: DrumGroove): string | null {
  if (slots.length !== 4) return 'The ensemble has four slots. Set unused slots to Off.';
  const used = new Map<EnsembleInstrument, number>();
  for (const [index, slot] of slots.entries()) {
    if (!slot || !isEnsembleChoice(slot.instrument)) return `Choose a supported instrument or Off in slot ${index + 1}.`;
    if (!Number.isFinite(slot.level) || slot.level < 0 || slot.level > 1 || typeof slot.muted !== 'boolean') {
      return `Slot ${index + 1} needs a level from 0 to 100% and a mute state.`;
    }
    if (slot.instrument === 'off') continue;
    const previous = used.get(slot.instrument);
    if (previous !== undefined) return `${ENSEMBLE_INSTRUMENTS[slot.instrument]} is already in slot ${previous + 1}. Choose a different instrument or Off in slot ${index + 1}.`;
    used.set(slot.instrument, index);
  }
  if (!used.size) return 'All four slots are Off. Choose at least one instrument to start the ensemble.';
  return used.has('drums') ? ensembleDrumProblem(drum) : null;
}

/** The existing eight-pulse hand patterns become eighth notes, without remapping their instruments. */
function pulseLanes(id: string, instrument: 'conga' | 'bongos'): GrooveLanes {
  const preset = RHYTHM_PRESETS.find(pattern => pattern.id === id);
  if (!preset || preset.beats !== 8 || preset.pattern.length !== 8) throw new Error(`The ${instrument} ensemble pattern needs eight pulses.`);
  const lanes: Partial<Record<GrooveLane, number[]>> = {};
  preset.pattern.forEach((stroke, index) => {
    const lane = HAND_LANES[instrument].find(candidate => GROOVE_LANES[candidate].voice === stroke.type);
    if (!lane) throw new Error(`The ${instrument} pattern contains an unsupported instrument.`);
    (lanes[lane] ??= new Array(16).fill(0))[index * 2] = stroke.vel;
  });
  return lanes;
}

function handPattern(instrument: Exclude<EnsembleInstrument, 'drums'>): GrooveLanes {
  if (instrument === 'conga') return pulseLanes('conga_practice', instrument);
  if (instrument === 'bongos') return pulseLanes('bongo_practice', instrument);
  const groove = getDrumGroove(instrument === 'tabla' ? 'tabla-keharwa' : 'cajon')!;
  return Object.fromEntries(Object.entries(groove.main).filter(([lane]) => HAND_LANES[instrument].includes(lane as GrooveLane)));
}

/** One grid, count-in and bar plan. Only drums change for fills/sections; hand parts keep their cycles. */
export function withEnsemble(drum: DrumGroove, slots: readonly EnsembleSlot[]): DrumGroove {
  const problem = ensembleProblem(slots, drum);
  if (problem) throw new Error(problem);
  const hasDrums = slots.some(slot => slot.instrument === 'drums'), bars = hasDrums ? drum.bars : 1;
  const parts: EnsemblePart[] = [], main: GrooveLanes = {}, chorus: GrooveLanes = {}, fill: GrooveLanes = {};
  const occupied = new Set<GrooveLane>();
  const repeat = (lanes: GrooveLanes, count: number): GrooveLanes => Object.fromEntries(Object.entries(lanes)
    .map(([lane, steps]) => [lane, Array.from({ length: count }, () => steps!).flat()]));
  slots.forEach((slot, index) => {
    const instrument = slot.instrument;
    if (instrument === 'off') return;
    const hand = instrument === 'drums' ? null : handPattern(instrument);
    const lanes = instrument === 'drums'
      ? [...new Set<GrooveLane>(['crash', ...[drum.main, drum.chorus, drum.fill].flatMap(pattern => Object.keys(pattern) as GrooveLane[])])]
      : Object.keys(hand!) as GrooveLane[];
    for (const lane of lanes) {
      if (occupied.has(lane)) throw new Error(`Two ensemble parts use ${GROOVE_LANES[lane].label}. Choose separate instruments.`);
      occupied.add(lane);
    }
    parts.push({ layer: ENSEMBLE_LAYERS[index], instrument, pattern: ensemblePattern(instrument, drum), lanes, seed: TOUCH_SEEDS[instrument] });
    Object.assign(main, hand ? repeat(hand, bars) : drum.main);
    Object.assign(chorus, hand ? repeat(hand, bars) : drum.chorus);
    Object.assign(fill, hand ? repeat(hand, 1) : drum.fill);
  });
  return {
    ...drum, id: `ensemble:${hasDrums ? drum.id : 'hands'}:${slots.map(slot => slot.instrument).join('+')}`,
    name: parts.map(part => ENSEMBLE_INSTRUMENTS[part.instrument]).join(' + '),
    style: 'Ensemble', description: 'Recorded instruments sharing one 4/4 clock.', tip: 'Keep chord changes on the shared beat.',
    meter: '4/4', beatsPerBar: 4, stepsPerBeat: 4, stepsPerBar: 16, beatUnit: 'quarter', bars,
    swingUnit: hasDrums ? drum.swingUnit : 16, swing: hasDrums ? drum.swing : .5, kitGroove: hasDrums,
    main, chorus, fill, loop: false, accompaniment: undefined, ensemble: { parts, drumId: hasDrums ? drum.id : null },
  };
}
