import { CHORD_FORMULAS, CHORD_QUALITY_DISPLAY } from '../chords/definitions';
import { spellChordTone } from '../chords/spelling';
import { WESTERN_SCALES } from '../scales/definitions';
import { displayNote, scaleRootPc, spellScale } from '../scales/theory';
import { chordIdentity, PITCH_CLASSES } from '../songs/timing';
import { type ChordQuality, type NoteName } from '../types';

export const PLAYER_SCALES = [
  { id: 'major', label: 'Major', description: 'A major tonic, a major V and a leading tone on degree 7.' },
  { id: 'natural_minor', label: 'Natural minor', description: 'A minor tonic and minor v. The lowered seventh does not act as a leading tone.' },
  { id: 'harmonic_minor', label: 'Harmonic minor', description: 'Raise the seventh for a major V, dominant V7 and a diminished leading-tone chord.' },
  { id: 'dorian', label: 'Dorian', description: 'Minor with a natural sixth: try the major IV against the minor tonic.' },
  { id: 'mixolydian', label: 'Mixolydian', description: 'Major with a lowered seventh: try the major ♭VII and minor v.' },
] as const;
export type PlayerScaleId = typeof PLAYER_SCALES[number]['id'];
export interface PlayerHarmony { key: NoteName; scale: PlayerScaleId }
export const DEFAULT_PLAYER_HARMONY: Readonly<PlayerHarmony> = { key: 'G', scale: 'major' };

const KEYS: readonly NoteName[] = ['C', 'Db', 'D', 'Eb', 'E', 'F', 'F#', 'G', 'Ab', 'A', 'Bb', 'B'];
const ROMANS = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII'];
const TRIADS: readonly ChordQuality[] = ['Major', 'Minor', 'dim', 'aug'];

export function playerKeys(scale: PlayerScaleId): readonly NoteName[] {
  // D-flat minor needs double flats; offer the same tonic as C-sharp minor instead.
  return scale === 'natural_minor' || scale === 'harmonic_minor' ? KEYS.map(key => key === 'Db' ? 'C#' : key) : KEYS;
}

export function playerHarmony(key: string, scale: string): PlayerHarmony {
  if (!PLAYER_SCALES.some(option => option.id === scale)) throw new Error('Choose one of the listed scales.');
  const pc = PITCH_CLASSES[key];
  const spelling = playerKeys(scale as PlayerScaleId).find(candidate => PITCH_CLASSES[candidate] === pc);
  if (!spelling) throw new Error('Choose one of the listed keys.');
  return { key: spelling, scale: scale as PlayerScaleId };
}

export interface ScaleChord { chord: string; degree: string; quality: ChordQuality }
export interface PlayerScaleContext {
  harmony: PlayerHarmony;
  label: string;
  description: string;
  notes: string[];
  degrees: readonly string[];
  chords: ScaleChord[];
}

/** Stack thirds from the actual scale, rather than reusing major-key chord qualities. */
export function playerScaleContext(harmony: PlayerHarmony): PlayerScaleContext {
  const normalized = playerHarmony(harmony.key, harmony.scale);
  const scale = WESTERN_SCALES[normalized.scale];
  const definition = PLAYER_SCALES.find(option => option.id === normalized.scale)!;
  const notes = spellScale(normalized.key, scale);
  const chords = scale.intervals.map((root, index): ScaleChord => {
    const intervals = [0, 2, 4].map(offset => (scale.intervals[(index + offset) % 7] - root + 12) % 12);
    const quality = TRIADS.find(candidate => CHORD_FORMULAS[candidate].every((step, i) => step === intervals[i]));
    if (!quality) throw new Error('This scale does not have a supported triad.');
    const roman = quality === 'Minor' || quality === 'dim' ? ROMANS[index].toLowerCase() : ROMANS[index];
    const accidental = scale.degrees[index].replace(/\d/g, '');
    return {
      chord: notes[index].replaceAll('♯', '#').replaceAll('♭', 'b') + CHORD_QUALITY_DISPLAY[quality],
      degree: accidental + roman + (quality === 'dim' ? '°' : quality === 'aug' ? '+' : ''),
      quality,
    };
  });
  return { harmony: normalized, label: definition.label, description: definition.description, notes, degrees: scale.degrees, chords };
}

/** Advisory only: outside-scale chords remain editable and playable. */
export function outsideScaleNotes(chord: string, harmony: PlayerHarmony): string[] {
  const identity = chordIdentity(chord);
  if (!identity) return [];
  const normalized = playerHarmony(harmony.key, harmony.scale);
  const scale = WESTERN_SCALES[normalized.scale];
  const tonic = scaleRootPc(normalized.key), root = PITCH_CLASSES[identity.root];
  return [...new Set(CHORD_FORMULAS[identity.quality].map(interval => (root + interval) % 12))]
    .filter(pc => !scale.intervals.includes((pc - tonic + 12) % 12))
    .map(pc => displayNote(spellChordTone(chord.match(/^[A-G][#b]?/)![0], identity.quality, pc)));
}
