/** Camera presets and playback steps for the 3D guitar stage; free of three.js so callers can import it eagerly. */

export type StageView = 'front' | 'player' | 'fretting' | 'strumming' | 'split' | 'guitar' | 'fretboard';

export const STAGE_VIEWS: readonly { id: StageView; label: string; title: string; primary?: boolean }[] = [
  { id: 'guitar', label: 'Guitar', title: 'The whole guitar', primary: true },
  { id: 'fretting', label: 'Chord hand', title: 'Close-up of the fretting hand on the chord', primary: true },
  { id: 'strumming', label: 'Strum hand', title: 'Close-up of the strumming or picking hand', primary: true },
  { id: 'split', label: 'Split', title: 'Chord hand and strum hand side by side', primary: true },
  { id: 'front', label: 'Front', title: 'Facing the guitarist, as a student watches a teacher' },
  { id: 'player', label: 'Player', title: 'First-person: looking down at the neck as you do while playing' },
  { id: 'fretboard', label: 'Fretboard', title: 'Note or finger markers on the neck, without hands' },
];

export const DEFAULT_STAGE_VIEW: StageView = 'guitar';

export interface StageClipChoice { name: string; label: string; kind: 'chord' | 'motion' }
export interface StageModelStatus {
  model: 'apk';
  state: 'idle' | 'loading' | 'ready' | 'failed';
  message: string;
  clips: readonly StageClipChoice[];
  preview: string | null;
}

export function isStageView(value: unknown): value is StageView {
  return typeof value === 'string' && STAGE_VIEWS.some(view => view.id === value);
}

export type StageFamily = 'strum' | 'pick';
/** Rests keep the strumming arm swinging just above the strings, as real players do. */
export type StageStroke = 'down' | 'up' | 'pluck' | 'rest';

export interface StageStep {
  /** Audio-clock time of the step, in seconds. */
  at: number;
  stepSeconds: number;
  /** Chord shape held during the step (app order: index 0 is the high e); null keeps the current shape. */
  frets: readonly (number | null)[] | null;
  family: StageFamily;
  stroke: StageStroke;
  stepInBar: number;
  notes: readonly { stringIndex: number; offset: number }[];
}
