import { chordBoxSvg } from './chordBox';
import {
  CHORD_GAME_LEVELS, CHORD_GAME_PASS, CHORD_GAME_ROUNDS, CHORD_GAME_STORAGE_KEY, CHORD_GAME_TIERS,
  buildRounds, chordPitchSet, isUnlocked, mulberry32, parseProgress, recordScore, spokenChord, starsFor, totalStars,
  type ChordGameLevel, type ChordGameMode, type ChordGameProgress, type ChordGameRound,
} from '../rhythm/chordGameLevels';
import { displayChordName, playableVoicings } from '../rhythm/chordPlayerPlan';
import { PITCH_CLASSES } from '../songs/timing';
import { getGuitarLook, onGuitarLookChange } from './guitarLook';
import type { StringTuning } from '../types';

export interface ChordGameActions {
  /** Strum a shape on the recorded guitar; rejects with a readable message when audio is unavailable. */
  strum(frets: readonly (number | null)[], tuning: readonly StringTuning[]): Promise<void>;
}

type GameView = 'map' | 'play' | 'result';
const MODE_WORDS: Record<ChordGameMode, string> = { see: 'Look', hear: 'Listen', find: 'Find' };
const escapeHtml = (text: string): string => text.replace(/[&<>"']/g, c => `&#${c.charCodeAt(0)};`);

function stars(count: number, total = 3): string {
  return Array.from({ length: total }, (_, i) => `<span class="chord-game-star${i < count ? ' is-on' : ''}">★</span>`).join('');
}

function markup(): string {
  return `
    <div class="card-header chord-game-header">
      <div class="chord-game-heading">
        <h3 id="chord-game-heading">Chord game</h3>
        <p class="chord-game-intro">Twenty-five levels. Name chords from their charts and by ear, then find the right shape. No microphone needed.</p>
      </div>
      <p id="chord-game-total" class="chord-game-total"></p>
    </div>
    <div id="chord-game-map" class="chord-game-map"></div>
    <div id="chord-game-play" class="chord-game-play" hidden>
      <div class="chord-game-top">
        <button type="button" class="btn btn-secondary" data-game="levels">All levels</button>
        <p id="chord-game-level" class="chord-game-level"></p>
        <p id="chord-game-count" class="chord-game-count"></p>
      </div>
      <ol id="chord-game-pips" class="chord-game-pips" aria-hidden="true"></ol>
      <div class="chord-game-stage">
        <div class="chord-game-ask">
          <h4 id="chord-game-question" class="chord-game-question" tabindex="-1"></h4>
          <div id="chord-game-prompt" class="chord-game-prompt"></div>
        </div>
        <div id="chord-game-options" class="chord-game-options" role="group" aria-labelledby="chord-game-question"></div>
      </div>
      <div class="chord-game-after">
        <p id="chord-game-feedback" class="chord-game-feedback" role="status" aria-live="polite"></p>
        <div class="chord-game-after-actions">
          <button type="button" class="btn btn-secondary" data-game="hear-answer" hidden>Hear it</button>
          <button type="button" class="btn btn-primary" data-game="next" hidden>Next round</button>
        </div>
      </div>
      <p id="chord-game-tip" class="chord-game-tip"></p>
    </div>
    <div id="chord-game-result" class="chord-game-result" hidden>
      <h4 id="chord-game-result-title" class="chord-game-result-title" tabindex="-1"></h4>
      <p id="chord-game-result-stars" class="chord-game-result-stars"></p>
      <p id="chord-game-result-text" class="chord-game-result-text"></p>
      <div class="chord-game-result-actions">
        <button type="button" class="btn btn-primary" data-game="next-level">Next level</button>
        <button type="button" class="btn btn-secondary" data-game="retry">Play again</button>
        <button type="button" class="btn btn-secondary" data-game="levels">All levels</button>
      </div>
    </div>`;
}

export class ChordGame {
  private readonly abort = new AbortController();
  private progress: ChordGameProgress;
  private view: GameView = 'map';
  private level: ChordGameLevel | null = null;
  private rounds: ChordGameRound[] = [];
  private round = 0;
  private results: boolean[] = [];
  private choice: string | null = null;
  private chartFallback = false;
  private improved = false;
  private notice = '';
  private soundRequest = 0;
  private mirrored = getGuitarLook().hand === 'left';

  constructor(private readonly root: HTMLElement, private tuning: readonly StringTuning[], private readonly actions: ChordGameActions) {
    this.progress = parseProgress(this.read());
    root.innerHTML = markup();
    this.listen();
    onGuitarLookChange(look => {
      const mirrored = look.hand === 'left';
      if (mirrored === this.mirrored) return;
      this.mirrored = mirrored;
      if (this.view === 'play') this.renderRound(false);
    }, this.abort.signal);
    this.render();
  }

  /** The game teaches shapes from the nut, so it uses the selected tuning without the capo. */
  setTuning(tuning: readonly StringTuning[]): void {
    if (tuning.map(s => s.midi).join() === this.tuning.map(s => s.midi).join()) return;
    this.tuning = tuning;
    if (this.view === 'play') this.renderRound(false);
    else this.render();
  }

  /** Read-only view for automated checks. */
  snapshot(): { view: GameView; level: number | null; round: number; answer: string | null; mode: ChordGameMode | null; score: number; answered: boolean } {
    const round = this.rounds[this.round];
    return {
      view: this.view, level: this.level?.id ?? null, round: this.round, answer: round?.answer ?? null, mode: round?.mode ?? null,
      score: this.results.filter(Boolean).length, answered: this.choice !== null,
    };
  }

  dispose(): void {
    this.abort.abort();
    this.soundRequest++;
  }

  private el<T extends HTMLElement = HTMLElement>(id: string): T {
    const node = this.root.querySelector<T>(`#chord-game-${id}`);
    if (!node) throw new Error(`Chord game element ${id} is missing.`);
    return node;
  }

  private read(): string | null {
    try { return localStorage.getItem(CHORD_GAME_STORAGE_KEY); } catch { return null; }
  }

  private write(): void {
    try { localStorage.setItem(CHORD_GAME_STORAGE_KEY, JSON.stringify(this.progress)); } catch { /* Progress stays for this visit. */ }
  }

  private shape(chord: string): (number | null)[] | null {
    return playableVoicings(chord, this.tuning)[0]?.frets ?? null;
  }

  /** Question charts carry no name or root markers, so neither the picture nor its label gives the answer away. */
  private box(chord: string, revealRoots = false): string {
    const frets = this.shape(chord);
    if (!frets) return '';
    const rootPc = PITCH_CLASSES[chord.match(/^[A-G][#b]?/)?.[0] ?? ''];
    return chordBoxSvg({
      frets, mirrored: this.mirrored,
      roots: revealRoots && rootPc !== undefined ? frets.map((fret, s) => fret !== null && (this.tuning[s].midi + fret) % 12 === rootPc) : undefined,
    });
  }

  private listen(): void {
    const signal = this.abort.signal;
    this.root.addEventListener('click', event => {
      const target = (event.target as HTMLElement).closest<HTMLElement>('[data-level], [data-option], [data-game]');
      if (!target || !this.root.contains(target)) return;
      if (target.dataset.level) this.openLevel(Number(target.dataset.level));
      else if (target.dataset.option !== undefined) this.answer(target.dataset.option);
      else this.command(target.dataset.game!);
    }, { signal });
    this.root.addEventListener('keydown', event => {
      if (this.view !== 'play' || this.choice !== null || event.altKey || event.ctrlKey || event.metaKey) return;
      if ((event.target as HTMLElement).closest('input, select, textarea')) return;
      const index = ['1', '2', '3', '4'].indexOf(event.key);
      const option = this.rounds[this.round]?.options[index];
      if (option === undefined) return;
      event.preventDefault();
      this.answer(option);
    }, { signal });
  }

  private command(name: string): void {
    if (name === 'levels') this.showMap(this.level?.id ?? null);
    else if (name === 'retry' && this.level) this.openLevel(this.level.id);
    else if (name === 'next-level' && this.level) this.openLevel(this.level.id + 1);
    else if (name === 'next') this.nextRound();
    else if (name === 'play' || name === 'hear-answer') void this.playAnswer();
  }

  private openLevel(id: number): void {
    const game = CHORD_GAME_LEVELS[id - 1];
    if (!game) return;
    if (!isUnlocked(id, this.progress)) {
      this.notice = `Score ${CHORD_GAME_PASS} or more in level ${id - 1} to unlock level ${id}.`;
      this.showMap(id);
      return;
    }
    const rounds = buildRounds(game, mulberry32(Math.floor(Math.random() * 2 ** 32)), {
      available: chord => this.shape(chord) !== null,
      conflicts: (a, b) => {
        if (a === b) return true;
        const notesA = chordPitchSet(a), notesB = chordPitchSet(b);
        if (notesA !== null && notesA === notesB) return true;
        return JSON.stringify(this.shape(a)) === JSON.stringify(this.shape(b));
      },
    });
    if (!rounds.length) {
      this.notice = `Level ${id} needs chords that have no playable shape in this tuning. Switch to standard tuning to play it.`;
      this.showMap(id);
      return;
    }
    this.level = game;
    this.rounds = rounds;
    this.round = 0;
    this.results = [];
    this.notice = '';
    this.view = 'play';
    this.render();
    this.renderRound(true);
  }

  private showMap(focusLevel: number | null): void {
    this.soundRequest++;
    this.view = 'map';
    this.render();
    if (focusLevel !== null) this.root.querySelector<HTMLElement>(`[data-level="${focusLevel}"]`)?.focus();
  }

  private answer(option: string): void {
    const round = this.rounds[this.round];
    if (this.view !== 'play' || !round || this.choice !== null || !round.options.includes(option)) return;
    this.choice = option;
    this.results.push(option === round.answer);
    this.renderRound(false);
    this.root.querySelector<HTMLButtonElement>('[data-game="next"]')?.focus();
  }

  private nextRound(): void {
    if (this.view !== 'play' || this.choice === null) return;
    if (this.round + 1 < this.rounds.length) {
      this.round++;
      this.renderRound(true);
      return;
    }
    const score = this.results.filter(Boolean).length;
    const recorded = recordScore(this.progress, this.level!.id, score);
    this.progress = recorded.progress;
    this.improved = recorded.improved;
    this.write();
    this.soundRequest++;
    this.view = 'result';
    this.render();
    this.el('result-title').focus();
  }

  private async playAnswer(): Promise<void> {
    const round = this.rounds[this.round];
    const frets = round ? this.shape(round.answer) : null;
    if (!frets) return;
    const request = ++this.soundRequest;
    try {
      await this.actions.strum(frets, this.tuning);
    } catch (error) {
      if (request !== this.soundRequest || this.view !== 'play') return;
      const message = error instanceof Error ? error.message : 'Sound is unavailable.';
      const result = this.resultFeedback();
      if (result) {
        this.setFeedback(`${result.text} ${message}`, result.state);
      } else if (round.mode === 'hear') {
        this.chartFallback = true;
        this.renderRound(false);
        this.setFeedback(`${message} Showing the chart instead.`, 'error');
      } else {
        this.setFeedback(message, 'error');
      }
    }
  }

  private resultFeedback(): { text: string; state: 'right' | 'wrong' } | null {
    const round = this.rounds[this.round];
    if (!round || this.choice === null) return null;
    const said = spokenChord(round.answer);
    return this.choice === round.answer
      ? { text: `Correct. That is ${said}.`, state: 'right' }
      : { text: `Not quite. That was ${said}, not ${spokenChord(this.choice)}.`, state: 'wrong' };
  }

  private setFeedback(text: string, state: 'right' | 'wrong' | 'error' | '' = ''): void {
    const feedback = this.el('feedback');
    feedback.textContent = text;
    if (state) feedback.dataset.state = state; else delete feedback.dataset.state;
  }

  private render(): void {
    const total = totalStars(this.progress);
    this.el('total').innerHTML = `<span aria-hidden="true">★</span> ${total} <span class="chord-game-total-of">/ ${CHORD_GAME_LEVELS.length * 3} stars</span>`;
    this.el('map').hidden = this.view !== 'map';
    this.el('play').hidden = this.view !== 'play';
    this.el('result').hidden = this.view !== 'result';
    if (this.view === 'map') this.renderMap();
    if (this.view === 'result') this.renderResult();
  }

  private renderMap(): void {
    const next = CHORD_GAME_LEVELS.find(l => isUnlocked(l.id, this.progress) && this.progress.best[l.id - 1] === null);
    const tiers = CHORD_GAME_TIERS.map(tier => {
      const first = tier.levels[0].id, last = tier.levels[tier.levels.length - 1].id;
      const buttons = tier.levels.map(l => {
        const best = this.progress.best[l.id - 1];
        const earned = starsFor(best);
        const unlocked = isUnlocked(l.id, this.progress);
        const state = !unlocked ? 'locked' : best !== null ? 'played' : 'open';
        const modes = [...new Set(l.modes)].map(m => MODE_WORDS[m]).join(' · ');
        const label = unlocked
          ? `Level ${l.id}, ${l.title}. ${modes}. ${best === null ? 'Not played yet' : `Best ${best} of ${CHORD_GAME_ROUNDS}, ${earned} of 3 stars`}.`
          : `Level ${l.id}, ${l.title}. Locked: score ${CHORD_GAME_PASS} or more in level ${l.id - 1} first.`;
        return `<li><button type="button" class="chord-game-level-btn" data-level="${l.id}" data-state="${state}"${l === next ? ' data-next' : ''} aria-label="${escapeHtml(label)}"${unlocked ? '' : ' aria-disabled="true"'}>
          <span class="chord-game-level-num" aria-hidden="true">${l.id}</span>
          <span class="chord-game-level-name" aria-hidden="true">${escapeHtml(l.title)}</span>
          <span class="chord-game-level-meta" aria-hidden="true">${unlocked ? escapeHtml(modes) : 'Locked'}</span>
          <span class="chord-game-level-stars" aria-hidden="true">${stars(earned)}</span>
        </button></li>`;
      }).join('');
      return `<li class="chord-game-tier"><h4 class="chord-game-tier-title">${escapeHtml(tier.title)} <span>Levels ${first}–${last}</span></h4><ol class="chord-game-levels">${buttons}</ol></li>`;
    }).join('');
    this.el('map').innerHTML = `
      <p class="chord-game-map-note" role="status">${escapeHtml(this.notice || `Score ${CHORD_GAME_PASS} or more out of ${CHORD_GAME_ROUNDS} to unlock the next level. 9 or more earns three stars.`)}</p>
      <ol class="chord-game-tiers">${tiers}</ol>`;
  }

  private renderRound(fresh: boolean): void {
    const game = this.level, round = this.rounds[this.round];
    if (!game || !round) return;
    if (fresh) {
      this.choice = null;
      this.chartFallback = false;
      this.setFeedback('');
    }
    const answered = this.choice !== null;
    const name = displayChordName(round.answer);
    this.el('level').innerHTML = `<span>Level ${game.id}</span> ${escapeHtml(game.title)}`;
    const score = this.results.filter(Boolean).length;
    this.el('count').textContent = `Round ${this.round + 1} of ${this.rounds.length} · ${score} correct`;
    this.el('pips').innerHTML = this.rounds.map((_, i) => {
      const state = i < this.results.length ? (this.results[i] ? 'right' : 'wrong') : i === this.round ? 'current' : 'todo';
      return `<li data-state="${state}"></li>`;
    }).join('');
    this.el('tip').innerHTML = `<span class="chord-game-tip-label">Tip</span> ${escapeHtml(game.tip)}`;
    this.el('play').dataset.mode = round.mode;

    const question = this.el('question');
    const prompt = this.el('prompt');
    if (round.mode === 'see') {
      question.textContent = 'Which chord is this?';
      prompt.innerHTML = `<div class="chord-game-chart">${this.box(round.answer, answered)}</div>`;
    } else if (round.mode === 'hear') {
      question.textContent = 'Which chord did you hear?';
      const chart = answered || this.chartFallback ? `<div class="chord-game-chart">${this.box(round.answer, answered)}</div>` : '';
      prompt.innerHTML = `<button type="button" class="chord-game-listen" data-game="play"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9v6h4l5 4V5L8 9H4z" fill="currentColor"/><path d="M16 8.5a5 5 0 0 1 0 7M18.5 6a8.5 8.5 0 0 1 0 12" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg><span>Play again</span></button>${chart}`;
    } else {
      question.innerHTML = `Find <span class="chord-game-target">${escapeHtml(name)}</span><span class="sr-only"> (${escapeHtml(spokenChord(round.answer))})</span>`;
      prompt.innerHTML = '';
    }

    this.el('options').innerHTML = round.options.map((option, i) => {
      const result = !answered ? '' : option === round.answer ? 'right' : option === this.choice ? 'wrong' : 'other';
      const body = round.mode === 'find'
        ? `<span class="chord-game-option-chart">${this.box(option, answered && option === round.answer)}</span>${answered ? `<span class="chord-game-option-reveal">${escapeHtml(displayChordName(option))}</span>` : ''}`
        : `<span class="chord-game-option-name" aria-hidden="true">${escapeHtml(displayChordName(option))}</span><span class="sr-only">${escapeHtml(spokenChord(option))}</span>`;
      return `<button type="button" class="chord-game-option" data-option="${escapeHtml(option)}"${result ? ` data-result="${result}"` : ''}${answered ? ' disabled' : ''}><span class="chord-game-key" aria-hidden="true">${i + 1}</span><span class="sr-only">Answer ${i + 1}: </span>${body}</button>`;
    }).join('');

    const next = this.root.querySelector<HTMLButtonElement>('[data-game="next"]')!;
    next.hidden = !answered;
    next.textContent = this.round + 1 < this.rounds.length ? 'Next round' : 'See your score';
    this.root.querySelector<HTMLButtonElement>('[data-game="hear-answer"]')!.hidden = !answered || round.mode === 'hear';
    const result = this.resultFeedback();
    if (result && !fresh) this.setFeedback(result.text, result.state);
    if (fresh) {
      question.focus({ preventScroll: true });
      if (round.mode === 'hear') void this.playAnswer();
    }
  }

  private renderResult(): void {
    const game = this.level!;
    const score = this.results.filter(Boolean).length;
    const earned = starsFor(score);
    const best = this.progress.best[game.id - 1] ?? score;
    const passed = score >= CHORD_GAME_PASS;
    const last = game.id === CHORD_GAME_LEVELS.length;
    this.el('result-title').textContent = passed ? (last ? 'You finished the chord game' : `Level ${game.id} complete`) : `Level ${game.id}: keep practising`;
    this.el('result-stars').innerHTML = `<span aria-hidden="true">${stars(earned)}</span><span class="sr-only">${earned} of 3 stars</span>`;
    const parts = [`${score} of ${CHORD_GAME_ROUNDS} correct.`];
    if (this.improved && score > 0) parts.push('New best score.');
    else parts.push(`Best so far: ${best} of ${CHORD_GAME_ROUNDS}.`);
    if (!passed) parts.push(last ? `Score ${CHORD_GAME_PASS} or more to finish the game.` : `Score ${CHORD_GAME_PASS} or more to unlock level ${game.id + 1}.`);
    else if (earned < 3) parts.push('Score 9 or more for three stars.');
    this.el('result-text').textContent = parts.join(' ');
    const nextLevel = this.root.querySelector<HTMLButtonElement>('[data-game="next-level"]')!;
    nextLevel.hidden = last || !isUnlocked(game.id + 1, this.progress);
  }
}
