import { CHORD_FORMULAS } from '../chords/definitions';
import { chordIdentity, PITCH_CLASSES } from '../songs/timing';
import type { ChordQuality } from '../types';

/** see: name the chart · hear: name the sound · find: pick the chart for a name. */
export type ChordGameMode = 'see' | 'hear' | 'find';

export interface ChordGameLevel {
  id: number;
  tier: string;
  title: string;
  modes: readonly ChordGameMode[];
  chords: readonly string[];
  tip: string;
}

export interface ChordGameRound { answer: string; options: string[]; mode: ChordGameMode }
export interface ChordGameProgress { version: 1; best: (number | null)[] }

export const CHORD_GAME_ROUNDS = 10;
export const CHORD_GAME_OPTIONS = 4;
export const CHORD_GAME_PASS = 5;
export const CHORD_GAME_STORAGE_KEY = 'gcs-chord-game-v1';

const OPEN = ['A', 'Am', 'C', 'D', 'Dm', 'E', 'Em', 'G'] as const;
const level = (id: number, tier: string, title: string, modes: ChordGameMode[], chords: readonly string[], tip: string): ChordGameLevel =>
  ({ id, tier, title, modes, chords, tip });

