export const CHORD_GAME_TIERS: readonly { title: string; levels: readonly ChordGameLevel[] }[] =
  [...new Set(CHORD_GAME_LEVELS.map(l => l.tier))].map(title => ({ title, levels: CHORD_GAME_LEVELS.filter(l => l.tier === title) }));

/** Deterministic generator for tests and replayable rounds. */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function shuffle<T>(items: T[], random: () => number): T[] {
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

/** Pitch-class set of a chord name, for example "C6" and "Am7" are both "0,4,7,9". */
export function chordPitchSet(name: string): string | null {
  const identity = chordIdentity(name);
  const rootPc = identity ? PITCH_CLASSES[name.match(/^[A-G][#b]?/)?.[0] ?? ''] : undefined;
  const formula = identity ? CHORD_FORMULAS[identity.quality] : undefined;
  if (!identity || rootPc === undefined || !formula) return null;
  return [...new Set(formula.map(step => (rootPc + step) % 12))].sort((a, b) => a - b).join(',');
}

export interface RoundOptions {
  /** False when the chord has no playable shape in the current tuning. */
  available?: (chord: string) => boolean;
  /** True when two chords cannot both be offered (same notes or the same shape). */
  conflicts?: (a: string, b: string) => boolean;
}

const sameNotes = (a: string, b: string): boolean => a === b || (chordPitchSet(a) !== null && chordPitchSet(a) === chordPitchSet(b));

/**
 * Ten rounds with four distinct answers each; every pool chord appears before any repeats.
 * Levels never list two names for the same notes (Asus2 and Esus4, Caug and Eaug), so one answer is always right.
 */
export function buildRounds(game: ChordGameLevel, random: () => number, options: RoundOptions = {}): ChordGameRound[] {
  const available = options.available ?? (() => true);
  const conflicts = options.conflicts ?? sameNotes;
  const pool = [...new Set(game.chords)].filter(available);
  const backup = [...new Set(CHORD_GAME_LEVELS.slice(0, game.id - 1).reverse().flatMap(l => l.chords))]
    .filter(chord => available(chord) && !pool.includes(chord));
  if (!pool.length || pool.length + backup.length < CHORD_GAME_OPTIONS) return [];

  const answers: string[] = [];
  while (answers.length < CHORD_GAME_ROUNDS) {
    const bag = shuffle([...pool], random);
    if (bag.length > 1 && bag[0] === answers[answers.length - 1]) [bag[0], bag[1]] = [bag[1], bag[0]];
    answers.push(...bag);
  }
  answers.length = CHORD_GAME_ROUNDS;
  const modes = shuffle(Array.from({ length: CHORD_GAME_ROUNDS }, (_, i) => game.modes[i % game.modes.length]), random);

  const rounds: ChordGameRound[] = [];
  for (const [i, answer] of answers.entries()) {
    const chosen: string[] = [answer];
    for (const candidate of [...shuffle(pool.filter(c => c !== answer), random), ...shuffle([...backup], random)]) {
      if (chosen.length === CHORD_GAME_OPTIONS) break;
      if (!chosen.some(other => conflicts(other, candidate))) chosen.push(candidate);
    }
    if (chosen.length < CHORD_GAME_OPTIONS) return [];
    rounds.push({ answer, options: shuffle(chosen, random), mode: modes[i] });
  }
  return rounds;
}

export function starsFor(score: number | null | undefined): 0 | 1 | 2 | 3 {
  if (score === null || score === undefined) return 0;
  return score >= 9 ? 3 : score >= 7 ? 2 : score >= CHORD_GAME_PASS ? 1 : 0;
}

export function isUnlocked(levelId: number, progress: ChordGameProgress): boolean {
  return levelId <= 1 || (progress.best[levelId - 2] ?? 0) >= CHORD_GAME_PASS;
}

export function totalStars(progress: ChordGameProgress): number {
  return progress.best.reduce<number>((sum, score) => sum + starsFor(score), 0);
}

export function emptyProgress(): ChordGameProgress {
  return { version: 1, best: Array<number | null>(CHORD_GAME_LEVELS.length).fill(null) };
}

/** Accepts stored progress only when it has the expected shape; anything else starts fresh. */
export function parseProgress(raw: string | null | undefined): ChordGameProgress {
  const fresh = emptyProgress();
  if (!raw) return fresh;
  try {
    const data = JSON.parse(raw) as { version?: unknown; best?: unknown };
    if (data?.version !== 1 || !Array.isArray(data.best)) return fresh;
    fresh.best = fresh.best.map((_, i) => {
      const value = (data.best as unknown[])[i];
      return Number.isInteger(value) && (value as number) >= 0 && (value as number) <= CHORD_GAME_ROUNDS ? value as number : null;
    });
    return fresh;
  } catch {
    return fresh;
  }
}

export function recordScore(progress: ChordGameProgress, levelId: number, score: number): { progress: ChordGameProgress; improved: boolean } {
  const best = [...progress.best];
  const previous = best[levelId - 1];
  const improved = previous === null || previous === undefined || score > previous;
  if (improved) best[levelId - 1] = score;
  return { progress: { version: 1, best }, improved };
}

const QUALITY_WORDS: Partial<Record<ChordQuality, string>> = {
  Major: 'major', Minor: 'minor', '7': 'seven', maj7: 'major seven', m7: 'minor seven', sus2: 'sus two', sus4: 'sus four',
  '5': 'five (power chord)', dim: 'diminished', aug: 'augmented', '6': 'six', m6: 'minor six', add9: 'add nine', '9': 'nine',
  m9: 'minor nine', maj9: 'major nine', '11': 'eleven', '13': 'thirteen', '7sus4': 'seven sus four', m7b5: 'minor seven flat five',
  dim7: 'diminished seven', m11: 'minor eleven', add11: 'add eleven',
};

/** Words for screen readers, for example "F sharp minor" or "B flat major". */
export function spokenChord(name: string): string {
  const identity = chordIdentity(name);
  const root = name.match(/^([A-G])([#b])?/);
  if (!identity || !root) return name;
  const accidental = root[2] === '#' ? ' sharp' : root[2] === 'b' ? ' flat' : '';
  return `${root[1]}${accidental} ${QUALITY_WORDS[identity.quality] ?? identity.quality}`;
}
