const STAGE_STROKES: Record<PlayerPlan['steps'][number]['cue']['kind'], StageStroke> = {
  down: 'down', light: 'down', up: 'up', pluck: 'pluck', rest: 'rest', count: 'rest',
};

function readStagePrefs(): StagePrefs {
  let raw: unknown = null;
  try { raw = JSON.parse(localStorage.getItem(STAGE_PREFS_KEY) || 'null'); } catch { /* Defaults below. */ }
  const value = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
  return {
    view: isStageView(value.view) ? value.view : DEFAULT_STAGE_VIEW,
    labels: value.labels === 'fingers' ? 'fingers' : 'notes',
    hands: value.hands !== false,
  };
}

