const errorText = (error: unknown): string => error instanceof Error ? error.message : String(error);
const beatName = (step: number): string => `Beat ${Math.floor(step / 2) + 1}${step % 2 ? ' and' : ''}`;
/** Low E → high E, the order guitarists read chord charts. */
const shapeCode = (frets: readonly (number | null)[]): string => [...frets].reverse().map(f => f === null ? '×' : String(f)).join(' ');
const shapeWords = (frets: readonly (number | null)[]): string =>
  [...frets].reverse().map(f => f === null ? 'muted' : f === 0 ? 'open' : `fret ${f}`).join(', ');
const escapeHtml = (text: string): string => text.replace(/[&<>"']/g, c => `&#${c.charCodeAt(0)};`);
/** Everything that changes what the player hears; renaming or saving does not. */
const musicKey = (song: PlayerSong): string => JSON.stringify([song.bpm, song.patternId, song.loop, song.chords]);

function sequenceName(chords: readonly PlayerChord[]): string {
  const full = chords.map(c => displayChordName(c.chord)).join(' – ') || 'My progression';
  if (full.length <= PLAYER_LIMITS.maxName) return full;
  const cut = full.slice(0, PLAYER_LIMITS.maxName - 2);
  const at = cut.lastIndexOf(' – ');
  return `${(at > 0 ? cut.slice(0, at) : cut).trimEnd()} …`;
}

