export class ChordPlayer {
  private store: PlayerStore;
  private tuning: StringTuning[];
  private preview!: PlayerPlan;
  private chordAt: number[] = [];
  private plan: PlayerPlan | null = null;
  private stepIndex = -1;
  private selected = 0;
  private active = false;
  private mode: PlayerMode = 'build';
  private pending = false;
  private generation = 0;
  private audio: PlayerAudio | null = null;
  private readonly sources = new Map<AudioBufferSourceNode, number>();
  private readonly clicks = new Set<() => void>();
  private undoState: { store: PlayerStore; selected: number; label: string } | null = null;
  private restartTimer = 0;
  private storageBlocked = false;
  private readonly nodes = new Map<string, HTMLElement>();
  private flatCells: HTMLButtonElement[] = [];
  private flatLabels: HTMLElement[] = [];
  private gridCells: HTMLElement[] = [];
  private readonly cellHtml: string[] = Array<string>(STRINGS.length * FRET_COUNT).fill('');
  private gridKey = '';
  private boxKey = '';
  private harmonyKey = '';
  private prefs: StagePrefs = readStagePrefs();
  private look: GuitarLook = getGuitarLook();
  private stage: GuitarStage3D | null = null;
  private readonly abort = new AbortController();
  private readonly neck: PaneNeck3D;
  private readonly transport: SongTransport;

  constructor(private readonly host: HTMLElement, tuning: readonly StringTuning[], private capo: number, private readonly actions: ChordPlayerActions) {
    this.tuning = tuning.map(string => ({ ...string }));
    let raw: string | null = null;
    try { raw = localStorage.getItem(PLAYER_STORAGE_KEY); } catch { this.storageBlocked = true; }
    this.store = parsePlayerStore(raw);
    host.innerHTML = markup();
    this.buildFlatNeck();
    this.buildGrid();
    this.neck = new PaneNeck3D(this.el('3d'), {
      toggle3d: this.el('view-3d'), toggle2d: this.el('view-2d'), twoD: this.el('2d'), camera: this.el('camera'),
      zoomIn: this.el('zoom-in'), zoomOut: this.el('zoom-out'), reset: this.el('reset'), help: this.el('help'),
      only3d: [this.el('views'), this.el('hands-option'), this.el('scene-controls')],
    }, (s, f) => this.pick(s, f), {
      defaultMode: '3d', preferenceKey: 'gcs-chord-player-neck-view',
      help2d: 'Tab to a marked fret, then Enter to hear it. While playing, dashed dots show where the next chord goes.',
      loadScene: () => import('./guitarStage3d').then(module => module.GuitarStage3D),
      onScene: scene => this.attachStage(scene as GuitarStage3D | null),
    });
    this.neck.setActive(false);
    this.transport = new SongTransport({
      now: () => this.audio?.context.currentTime ?? 0,
      setTimer: (callback, milliseconds) => window.setTimeout(callback, milliseconds),
      clearTimer: id => window.clearTimeout(id),
    }, {
      play: (entry, start) => this.playStep(entry.index, start),
      target: entry => { this.stepIndex = entry.index; this.renderNow(); },
      finish: () => {
        this.plan = null; this.stepIndex = -1;
        this.status('Finished. Press Play to hear it again, or turn on Loop.');
        this.renderNow();
      },
      stalled: () => this.status('Audio timing was interrupted; continuing without rushing.'),
    });
    this.listen();
    this.renderStageBar();
    this.renderModelStatus(null);
    this.renderLook();
    this.refresh();
  }

  private get song(): PlayerSong { return this.store.current; }
  private get harmony(): PlayerHarmony { return this.song.harmony ?? DEFAULT_PLAYER_HARMONY; }

  private setMode(mode: PlayerMode, focus = false): void {
    if (mode === 'build' && this.busy) this.stop('Stopped so you can build your progression.');
    this.mode = mode;
    for (const candidate of ['build', 'player'] as const) {
      const tab = this.el(`${candidate}-tab`);
      tab.setAttribute('aria-selected', String(candidate === mode));
      tab.tabIndex = candidate === mode ? 0 : -1;
      this.el(candidate).hidden = candidate !== mode;
    }
    this.el('add').hidden = mode !== 'build';
    this.neck.setActive(this.active && mode === 'player');
    if (focus) this.el(`${mode}-tab`).focus();
  }

  /** Connects the full guitar stage once the shared pane creates it, and forgets it when the pane releases it. */
  private attachStage(stage: GuitarStage3D | null): void {
    this.stage = stage;
    if (!stage) {
      this.renderHandStatus('loading');
      this.renderModelStatus(null);
      return;
    }
    // Animate when the sound leaves the speakers, not when it is scheduled.
    stage.setClock(() => {
      const context = this.audio?.context;
      return context ? context.currentTime - (context.baseLatency || 0) - (context.outputLatency || 0) : performance.now() / 1000;
    });
    stage.onHandStatus = status => this.renderHandStatus(status);
    stage.onModelStatus = status => this.renderModelStatus(status);
    stage.setHandsVisible(this.prefs.hands);
    stage.setView(this.prefs.view);
    this.syncStageShapes();
    this.renderHandStatus(stage.getHandStatus());
    this.renderModelStatus(stage.getModelStatus());
  }

  private syncStageShapes(): void {
    if (!this.stage) return;
    if (!this.plan) this.stage.setFamily(this.preview.pattern.family);
    this.stage.prepareShapes(this.preview.chords.flatMap(chord => chord.voicing ? [chord.voicing.frets] : []));
  }

  private renderHandStatus(status: HandStatus): void {
    const input = this.el<HTMLInputElement>('hands');
    const failed = status === 'failed';
    input.disabled = failed;
    this.setText('hands-text', failed ? 'Hands unavailable' : status === 'loading' && this.stage && this.prefs.hands ? 'Hands · loading' : 'Hands');
    this.el('hands-option').title = failed ? 'The acoustic scene could not load. Retry or use the keyboard-accessible 2D view.' : 'Show the fretting and strumming hands';
  }

  private renderModelStatus(status: StageModelStatus | null): void {
    const original = status?.model === 'apk', ready = original && status.state === 'ready';
    this.el('original').hidden = !ready;
    this.el('retry-scene').hidden = !original || status.state !== 'failed';
    this.el('scene-status').hidden = !original;
    this.el('scene-status').dataset.error = String(status?.state === 'failed');
    this.setText('scene-status', original ? status.message : '');
    const select = this.el<HTMLSelectElement>('original-clip');
    if (ready && select.options.length !== status.clips.length) {
      select.innerHTML = ['motion', 'chord'].map(kind => `<optgroup label="${kind === 'motion' ? 'Strumming and fingerpicking' : 'Original chord poses'}">${
        status.clips.filter(clip => clip.kind === kind).map(clip => `<option value="${escapeHtml(clip.name)}">${escapeHtml(clip.label)}</option>`).join('')
      }</optgroup>`).join('');
      select.value = 'Acal';
    }
    this.el<HTMLButtonElement>('follow-original').disabled = !status?.preview;
    if (this.preview) this.renderCaption(this.preview.chords[this.displayIndex()]);
  }

  private setStagePrefs(patch: Partial<StagePrefs>): void {
    this.prefs = { ...this.prefs, ...patch };
    try { localStorage.setItem(STAGE_PREFS_KEY, JSON.stringify(this.prefs)); } catch { /* Optional preference. */ }
    this.renderStageBar();
    if (patch.view) this.stage?.setView(patch.view);
    if (patch.hands !== undefined) this.stage?.setHandsVisible(patch.hands);
    if (patch.labels) this.renderNow();
  }

  private renderStageBar(): void {
    this.el('views').querySelectorAll<HTMLButtonElement>('[data-view]').forEach(button => {
      button.setAttribute('aria-pressed', String(button.dataset.view === this.prefs.view));
    });
    const extra = STAGE_VIEWS.find(view => view.id === this.prefs.view && !view.primary);
    this.setText('more-view-label', extra ? `More views · ${extra.label}` : 'More views');
    this.el('more-view-label').dataset.active = String(Boolean(extra));
    this.el('labels').querySelectorAll<HTMLButtonElement>('[data-labels]').forEach(button => {
      button.setAttribute('aria-pressed', String(button.dataset.labels === this.prefs.labels));
    });
    this.el<HTMLInputElement>('hands').checked = this.prefs.hands;
  }

  private renderLook(): void {
    const look = this.el('look');
    look.querySelectorAll<HTMLInputElement>('input[name="chord-player-skin"]').forEach(input => { input.checked = input.value === this.look.skin; });
    this.el<HTMLInputElement>('lefty').checked = this.look.hand === 'left';
  }

  private el<T extends HTMLElement = HTMLElement>(id: string): T {
    let node = this.nodes.get(id);
    if (!node) {
      node = this.host.querySelector<HTMLElement>(`#chord-player-${id}`) ?? undefined;
      if (!node) throw new Error(`Chord player markup is missing #chord-player-${id}.`);
      this.nodes.set(id, node);
    }
    return node as T;
  }

  private buildFlatNeck(): void {
    const flat = this.el('2d');
    flat.innerHTML = `<div class="fret-numbers">${Array.from({ length: FRET_COUNT }, (_, f) => `<div class="fret-num">${f || 'Open'}</div>`).join('')}</div>`;
    for (const s of STRINGS) {
      const row = document.createElement('div'); row.className = 'guitar-string-row';
      row.innerHTML = `<div class="string-header"><span data-string-label="${s}"></span></div><div class="fret-cells-container"><div class="string-wire str-${s + 1}"></div>${Array.from({ length: FRET_COUNT }, (_, f) => `<button type="button" class="fret-cell" data-string="${s}" data-fret="${f}" disabled></button>`).join('')}</div>`;
      flat.append(row);
    }
    this.flatCells = [...flat.querySelectorAll<HTMLButtonElement>('[data-fret]')];
    this.flatLabels = [...flat.querySelectorAll<HTMLElement>('[data-string-label]')];
  }

  private buildGrid(): void {
    const grid = this.el('grid');
    grid.innerHTML = Array.from({ length: STEPS_PER_BAR }, () =>
      '<li class="strumming-step"><span aria-hidden="true"></span><strong aria-hidden="true"></strong><small aria-hidden="true"></small><span class="sr-only"></span></li>').join('');
    this.gridCells = [...grid.children] as HTMLElement[];
  }

  private listen(): void {
    const signal = this.abort.signal;
    const on = (id: string, type: string, handler: (event: Event) => void) => this.el(id).addEventListener(type, handler, { signal });
    const value = (id: string) => this.el<HTMLInputElement | HTMLSelectElement>(id).value;
    on('modes', 'click', event => {
      const mode = (event.target as HTMLElement).closest<HTMLElement>('[data-mode]')?.dataset.mode;
      if (mode === 'build' || mode === 'player') this.setMode(mode);
    });
    on('modes', 'keydown', event => {
      const key = (event as KeyboardEvent).key;
      if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(key)) return;
      event.preventDefault();
      this.setMode(key === 'Home' ? 'build' : key === 'End' ? 'player' : this.mode === 'build' ? 'player' : 'build', true);
    });
    on('to-player', 'click', () => { this.setMode('player'); this.el('play').focus(); });
    on('play', 'click', () => {
      if (this.plan || this.pending) this.stop();
      else void this.play(this.displayIndex(), this.song.countIn, true);
    });
    on('bpm', 'input', () => this.setTempo(Number(value('bpm')), false));
    on('bpm', 'change', () => this.setTempo(Number(value('bpm')), true));
    on('pattern', 'change', () => this.update({ ...this.song, patternId: value('pattern') }, { restart: 'current' }));
    on('loop', 'change', () => this.update({ ...this.song, loop: this.el<HTMLInputElement>('loop').checked }, { restart: 'current' }));
    on('count', 'change', () => this.update({ ...this.song, countIn: this.el<HTMLInputElement>('count').checked }));
    on('tiles', 'click', event => {
      const tile = (event.target as HTMLElement).closest<HTMLElement>('[data-index]');
      if (tile) this.select(Number(tile.dataset.index));
    });
    on('root', 'change', () => this.editSelected({ root: value('root') }, true));
    on('type', 'change', () => this.editSelected({ quality: value('type') as ChordQuality }, true));
    on('beats', 'change', () => this.editSelected({ beats: Number(value('beats')) as PlayerBeats }, false));
    on('voicing', 'change', () => this.editSelected({ voicing: value('voicing') }, true));
    on('hear', 'click', () => this.audition(this.selected));
    on('earlier', 'click', () => this.move(-1));
    on('later', 'click', () => this.move(1));
    on('remove', 'click', () => this.removeSelected());
    on('add', 'click', () => this.addChord());
    on('duplicate', 'click', () => this.addChord(undefined, true));
    on('undo', 'click', () => this.undo());
    on('use', 'click', () => this.usePreset());
    on('key', 'change', () => this.setHarmony(value('key'), value('scale')));
    on('scale', 'change', () => this.setHarmony(value('key'), value('scale')));
    on('preset', 'change', () => this.renderPreset());
    on('suggestions', 'click', event => {
      const chord = (event.target as HTMLElement).closest<HTMLElement>('[data-chord]')?.dataset.chord;
      if (chord) this.addChord(chord);
    });
    on('save', 'click', () => this.saveCurrent());
    on('save-name', 'keydown', event => {
      if ((event as KeyboardEvent).key === 'Enter') { event.preventDefault(); this.saveCurrent(); }
    });
    on('load', 'click', () => this.loadSaved());
    on('delete', 'click', () => this.deleteSaved());
    on('views', 'click', event => {
      const view = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-view]')?.dataset.view;
      if (!isStageView(view)) return;
      const more = this.el<HTMLDetailsElement>('more-views');
      const fromMore = more.contains(event.target as Node);
      this.setStagePrefs({ view });
      more.open = false;
      if (fromMore) this.el('more-view-label').focus();
    });
    on('labels', 'click', event => {
      const labels = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-labels]')?.dataset.labels;
      if (labels) this.setStagePrefs({ labels: labels === 'fingers' ? 'fingers' : 'notes' });
    });
    on('hands', 'change', () => this.setStagePrefs({ hands: this.el<HTMLInputElement>('hands').checked }));
    on('retry-scene', 'click', () => this.stage?.retryScene());
    on('preview-original', 'click', () => {
      if (!this.stage) return;
      this.stop('Paused for an original animation preview. Press Play to return to your progression.');
      this.setStagePrefs({ hands: true });
      try {
        this.stage.previewOriginalClip(value('original-clip'));
        this.el<HTMLDetailsElement>('original').open = false;
        this.el('original').querySelector('summary')?.focus();
      } catch (error) { this.status(`The original motion could not be previewed: ${errorText(error)}`, true); }
    });
    on('follow-original', 'click', () => {
      this.stage?.followProgression();
      this.el<HTMLDetailsElement>('original').open = false;
      this.el('original').querySelector('summary')?.focus();
      this.renderNow();
    });
    on('look', 'change', event => {
      const input = event.target as HTMLInputElement;
      if (input.name === 'chord-player-skin') setGuitarLook({ skin: input.value as SkinTone });
      else if (input.id === 'chord-player-lefty') setGuitarLook({ hand: input.checked ? 'left' : 'right' });
    });
    for (const id of ['look', 'more-views', 'original']) {
      on(id, 'keydown', event => {
        const panel = this.el<HTMLDetailsElement>(id);
        if ((event as KeyboardEvent).key !== 'Escape' || !panel.open) return;
        event.preventDefault();
        event.stopPropagation();
        panel.open = false;
        panel.querySelector('summary')?.focus();
      });
    }
    document.addEventListener('pointerdown', event => {
      for (const id of ['look', 'more-views', 'original']) {
        const panel = this.el<HTMLDetailsElement>(id);
        if (panel.open && !panel.contains(event.target as Node)) panel.open = false;
      }
    }, { signal });
    onGuitarLookChange(look => {
      this.look = look;
      this.renderLook();
      this.renderInspector();
      this.renderNow();
    }, signal);
    on('2d', 'click', event => {
      const cell = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-fret]');
      if (cell && !cell.disabled) this.pick(Number(cell.dataset.string), Number(cell.dataset.fret));
    });
    this.host.addEventListener('keydown', event => {
      if (event.key === 'Escape' && (this.plan || this.pending)) { event.preventDefault(); this.stop(); }
    }, { signal });
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) this.stop('Stopped because the page was hidden.');
    }, { signal });
    window.addEventListener('pagehide', () => this.stop('Stopped because the page was hidden.'), { signal });
  }

  private refresh(): void {
    try {
      this.preview = compilePlayerPlan(this.song, this.tuning, { countIn: false });
    } catch (error) {
      this.store = { ...this.store, current: defaultPlayerSong() };
      this.notice(`That progression could not be played (${errorText(error)}), so the starter progression is back.`, true);
      this.preview = compilePlayerPlan(this.song, this.tuning, { countIn: false });
    }
    this.chordAt = this.preview.chords.flatMap(chord => Array<number>(chord.steps).fill(chord.index));
    this.selected = Math.max(0, Math.min(this.selected, this.preview.chords.length - 1));
    this.renderSettings();
    this.renderTiles();
    this.renderHarmony();
    this.renderInspector();
    this.renderLibrary();
    this.renderNow();
    this.syncStageShapes();
  }

  private setText(id: string, text: string): void {
    const node = this.el(id);
    if (node.textContent !== text) node.textContent = text;
  }

  private status(text: string, error = false): void { this.message('status', text, error); }
  private notice(text: string, error = false): void { this.message('notice', text, error); }
  private message(id: string, text: string, error: boolean): void {
    const node = this.el(id);
    node.textContent = text;
    if (error) node.dataset.state = 'error'; else delete node.dataset.state;
  }

  private toneLabel(chord: ResolvedPlayerChord, stringIndex: number, fret: number): string {
    return displayNote(spellChordTone(chord.rootText, chord.quality, (this.tuning[stringIndex].midi + fret) % 12));
  }

  private renderSettings(): void {
    const song = this.song;
    const bpm = this.el<HTMLInputElement>('bpm');
    bpm.value = String(song.bpm);
    bpm.setAttribute('aria-valuetext', `${song.bpm} beats per minute`);
    this.setText('bpm-out', `${song.bpm} BPM`);
    this.el<HTMLSelectElement>('pattern').value = song.patternId;
    this.el<HTMLInputElement>('loop').checked = song.loop;
    this.el<HTMLInputElement>('count').checked = song.countIn;
    const pattern = this.preview.pattern;
    this.setText('pattern-name', `4/4 · ${pattern.family === 'pick' ? 'Fingerpicking' : 'Strumming'} · ${pattern.name}`);
    this.setText('pattern-description', `${pattern.description} Straight eighths: 1 & 2 & 3 & 4 &.`);
    this.setText('name', song.name);
    const scale = PLAYER_SCALES.find(candidate => candidate.id === this.harmony.scale)!;
    this.setText('meta', `${describeSong(song)} · ${song.bpm} BPM · ${displayNote(this.harmony.key)} ${scale.label.toLowerCase()}${this.storageBlocked ? ' · this browser is not saving changes' : ''}`);
    this.setText('tuning', `${[...this.tuning].reverse().map(string => displayNote(NOTE_NAMES[string.midi % 12])).join(' · ')}${this.capo ? ` · capo ${this.capo}` : ''}`);
    const undo = this.el<HTMLButtonElement>('undo');
    undo.hidden = !this.undoState;
    undo.textContent = this.undoState ? `Undo ${this.undoState.label}` : 'Undo';
  }

  private tileButton(index: number): HTMLButtonElement | null {
    return this.el('tiles').querySelector<HTMLButtonElement>(`[data-index="${index}"]`);
  }

  private renderTiles(): void {
    const list = this.el('tiles');
    const focused = document.activeElement instanceof HTMLElement && list.contains(document.activeElement)
      ? Number(document.activeElement.closest<HTMLElement>('[data-index]')?.dataset.index ?? -1) : -1;
    list.replaceChildren(...this.preview.chords.map(chord => {
      const item = document.createElement('li');
      const button = document.createElement('button');
      button.type = 'button';
      button.className = 'chord-player-tile';
      button.dataset.index = String(chord.index);
      if (!chord.voicing) button.dataset.shape = 'none';
      const name = displayChordName(chord.chord);
      button.setAttribute('aria-label', `Chord ${chord.index + 1}: ${name}, ${chord.beats} ${chord.beats === 1 ? 'beat' : 'beats'}${chord.voicing ? '' : ', no playable shape'}`);
      const title = document.createElement('span'); title.className = 'chord-player-tile-name'; title.textContent = name;
      const length = document.createElement('span'); length.className = 'chord-player-tile-beats'; length.textContent = TILE_BEATS[chord.beats];
      button.append(title, length);
      item.append(button);
      return item;
    }));
    if (focused >= 0) this.tileButton(Math.min(focused, this.preview.chords.length - 1))?.focus();
  }

  private renderInspector(): void {
    const chords = this.preview.chords;
    const chord = chords[this.selected];
    this.setText('editing', `Edit chord ${this.selected + 1} of ${chords.length} · ${displayChordName(chord.chord)}`);
    const outside = outsideScaleNotes(chord.chord, this.harmony);
    this.setText('chord-fit', outside.length ? `Outside this scale: ${outside.join(', ')}. Kept as chosen.` : 'Every chord tone is in the selected scale.');
    this.el('edit-box').innerHTML = this.chart(chord);
    const rootPc = PITCH_CLASSES[chord.rootText];
    const root = this.el<HTMLSelectElement>('root');
    root.replaceChildren(...ROOTS.map(name => PITCH_CLASSES[name] === rootPc ? chord.rootText : name).map(name => new Option(displayNote(name), name)));
    root.value = chord.rootText;
    const type = this.el<HTMLSelectElement>('type');
    type.replaceChildren(...LIBRARY_CHORD_QUALITIES.map(quality =>
      new Option(`${QUALITY_NAMES[quality] ?? quality} · ${displayChordName(chord.rootText + CHORD_QUALITY_DISPLAY[quality])}`, quality)));
    type.value = chord.quality;
    this.el<HTMLSelectElement>('beats').value = String(chord.beats);
    const voicing = this.el<HTMLSelectElement>('voicing');
    if (chord.options.length) {
      voicing.replaceChildren(...chord.options.map(option => new Option(`${option.name} · ${shapeCode(option.frets)}`, option.name)));
      voicing.value = chord.voicing?.name ?? chord.options[0].name;
      voicing.disabled = false;
    } else {
      // The select itself is disabled; a disabled placeholder option would never be selected, leaving the box blank.
      voicing.replaceChildren(new Option('No playable shape in this tuning', '', true, true));
      voicing.disabled = true;
    }
    const last = chords.length - 1;
    this.el<HTMLButtonElement>('earlier').disabled = this.selected === 0;
    this.el<HTMLButtonElement>('later').disabled = this.selected === last;
    this.el<HTMLButtonElement>('remove').disabled = chords.length <= 1;
    this.el<HTMLButtonElement>('hear').disabled = !chord.voicing;
    this.el<HTMLButtonElement>('add').disabled = chords.length >= PLAYER_LIMITS.maxChords;
    this.el<HTMLButtonElement>('duplicate').disabled = chords.length >= PLAYER_LIMITS.maxChords;
  }

  private setHarmony(key: string, scale: string): void {
    try {
      const harmony = playerHarmony(key, scale);
      if (this.update({ ...this.song, harmony }, { undo: 'key / scale' })) {
        this.notice('Key and scale updated. Your chords are unchanged; use a suggestion or load a progression to change them.');
      }
    } catch (error) { this.notice(errorText(error), true); }
  }

  private renderHarmony(): void {
    const context = playerScaleContext(this.harmony);
    const key = `${context.harmony.key}|${context.harmony.scale}`;
    if (key !== this.harmonyKey) {
      this.harmonyKey = key;
      const root = this.el<HTMLSelectElement>('key');
      root.replaceChildren(...playerKeys(context.harmony.scale).map(name => new Option(displayNote(name), name)));
      root.value = context.harmony.key;
      this.el<HTMLSelectElement>('scale').value = context.harmony.scale;
      this.setText('scale-description', context.description);
      this.el('scale-tones').innerHTML = context.notes.map((note, i) =>
        `<li><span>${escapeHtml(context.degrees[i])}</span><strong>${escapeHtml(note)}</strong></li>`).join('');
      this.el('suggestions').innerHTML = context.chords.map(chord =>
        `<button type="button" class="chord-player-scale-chord" data-chord="${escapeHtml(chord.chord)}" aria-label="Add ${escapeHtml(displayChordName(chord.chord))}, degree ${chord.degree}"><span>${chord.degree}</span><strong>${escapeHtml(displayChordName(chord.chord))}</strong></button>`).join('');
      const presets = this.el<HTMLSelectElement>('preset'), previous = presets.value;
      const choices = PLAYER_PROGRESSIONS.filter(preset => preset.scale === context.harmony.scale);
      presets.replaceChildren(...choices.map(preset => new Option(`${preset.title} · ${preset.label.replace(' (minor)', '')}`, preset.id)));
      if (choices.some(preset => preset.id === previous)) presets.value = previous;
    }
    this.el('suggestions').querySelectorAll<HTMLButtonElement>('button').forEach(button => {
      button.disabled = this.song.chords.length >= PLAYER_LIMITS.maxChords;
    });
    const outside = [...new Set(this.song.chords.filter(chord => outsideScaleNotes(chord.chord, this.harmony).length).map(chord => displayChordName(chord.chord)))];
    this.setText('scale-fit', outside.length ? `Outside-scale chords in your sequence: ${outside.join(', ')}. Manual and borrowed chords are always allowed.` : 'Your whole progression fits this scale.');
    this.renderPreset();
  }

  private renderPreset(): void {
    const preset = PLAYER_PROGRESSIONS.find(candidate => candidate.id === this.el<HTMLSelectElement>('preset').value);
    if (!preset) return;
    const song = presetSong(preset.id, this.harmony.key, this.song);
    this.setText('preset-preview', song.chords.map(chord => displayChordName(chord.chord)).join(' – '));
    this.setText('preset-description', `${preset.description} Use progression replaces the sequence; Undo brings it back.`);
  }

  private renderLibrary(): void {
    const saved = this.store.saved;
    const select = this.el<HTMLSelectElement>('saved');
    if (saved.length) {
      select.replaceChildren(...saved.map(song => new Option(`${song.name} · ${describeSong(song)}`, song.name)));
      select.value = saved.some(song => song.name === this.song.name) ? this.song.name : saved[0].name;
    } else {
      select.replaceChildren(new Option('No saved progressions yet', '', true, true));
    }
    select.disabled = !saved.length;
    this.el<HTMLButtonElement>('load').disabled = !saved.length;
    this.el<HTMLButtonElement>('delete').disabled = !saved.length;
    const name = this.el<HTMLInputElement>('save-name');
    if (document.activeElement !== name) name.value = this.song.name;
  }

  /** The chord the panel shows: the sounding chord while playing, the first chord during a count-in, else the selection. */
  private displayIndex(): number {
    const step = this.plan?.steps[this.stepIndex];
    const index = step?.kind === 'play' ? step.chordIndex : this.plan ? this.plan.order[0] : this.selected;
    return Math.max(0, Math.min(index, this.preview.chords.length - 1));
  }

  private renderNow(): void {
    const plan = this.plan;
    const step = plan?.steps[this.stepIndex] ?? null;
    const chords = this.preview.chords;
    const index = this.displayIndex();
    const chord = chords[index];
    const name = displayChordName(chord.chord);
    const counting = Boolean(plan) && (step ? step.kind === 'count' : plan!.loopStart > 0);
    const next = plan ? nextChordIndex(plan, index) : index + 1 < chords.length ? index + 1 : this.song.loop ? 0 : null;

    const phase = !plan ? (this.pending ? 'pending' : 'idle') : counting ? 'count' : 'play';
    const phaseNode = this.el('phase');
    phaseNode.dataset.phase = phase;
    this.setText('phase', phase === 'pending' ? 'Getting the guitar ready…'
      : phase === 'idle' ? 'Selected · Play starts here'
        : phase === 'count' ? `Count-in · get ready for ${name}` : `Now playing · chord ${index + 1} of ${chords.length}`);
    this.setText('chord', name);
    const voicing = chord.voicing;
    const shape = this.el('shape');
    const shapeKey = voicing ? `${voicing.name}|${shapeCode(voicing.frets)}` : 'none';
    if (shape.dataset.key !== shapeKey) {
      shape.dataset.key = shapeKey;
      if (voicing) {
        const visible = document.createElement('span');
        visible.setAttribute('aria-hidden', 'true');
        visible.textContent = `${voicing.name} · ${shapeCode(voicing.frets)}`;
        const spoken = document.createElement('span');
        spoken.className = 'sr-only';
        spoken.textContent = `${voicing.name}, low string to high: ${shapeWords(voicing.frets)}`;
        shape.replaceChildren(visible, spoken);
      } else shape.textContent = 'No playable shape in this tuning — it stays silent';
    }
    this.renderBox(chord);
    const tones = voicing ? [...new Set([...STRINGS].reverse().filter(s => voicing.frets[s] !== null)
      .map(s => this.toneLabel(chord, s, voicing.frets[s]!)))].join(' ') : '—';
    this.setText('notes', tones);
    this.setText('length', BEAT_LABELS[chord.beats]);
    this.setText('next', next === null ? 'End of progression' : displayChordName(chords[next].chord));

    const state = this.pending ? 'pending' : plan ? 'playing' : 'idle';
    const play = this.el<HTMLButtonElement>('play');
    play.dataset.state = state;
    this.setText('play', state === 'idle' ? 'Play' : 'Stop');

    const nowTile = plan && !counting ? index : -1;
    const nextTile = !plan ? -1 : counting ? index : next !== null && next !== index ? next : -1;
    this.el('tiles').querySelectorAll<HTMLButtonElement>('[data-index]').forEach(button => {
      const i = Number(button.dataset.index);
      button.setAttribute('aria-pressed', String(i === this.selected));
      const tileState = i === nowTile ? 'now' : i === nextTile ? 'next' : '';
      if (tileState) button.dataset.state = tileState; else delete button.dataset.state;
    });

    this.renderGrid(plan, step, chord.startStep, counting);
    this.renderNeck(chord, step, plan && next !== null && next !== index && step?.kind === 'play' ? next : null);
  }

  private renderGrid(plan: PlayerPlan | null, step: PlayerPlan['steps'][number] | null, idleStep: number, counting: boolean): void {
    const cells: GridCell[] = [];
    let bar: string;
    if (plan && counting) {
      for (let i = 0; i < STEPS_PER_BAR; i++) {
        const count = plan.steps[i];
        cells.push({ count: count.count, text: count.cue.text, kind: 'count', chord: '', label: `${beatName(i)}: ${count.cue.label}`, current: i === this.stepIndex });
      }
      bar = 'Count-in';
    } else {
      const songStep = step?.kind === 'play' ? step.songStep : idleStep;
      const barStart = songStep - (songStep % STEPS_PER_BAR);
      for (let i = 0; i < STEPS_PER_BAR; i++) {
        const at = barStart + i;
        if (at >= this.preview.songSteps) {
          cells.push({ count: STRUM_COUNTS[i], text: '', kind: 'end', chord: '', label: `${beatName(i)}: after the last chord`, current: false });
          continue;
        }
        const cue = this.preview.cues[at];
        const owner = this.preview.chords[this.chordAt[at]];
        const ownerName = displayChordName(owner.chord);
        cells.push({
          count: STRUM_COUNTS[i], text: cue.text, kind: cue.kind, chord: at === owner.startStep || i === 0 ? ownerName : '',
          label: `${beatName(i)}: ${cue.label}, ${ownerName}`, current: step?.kind === 'play' && step.songStep === at,
        });
      }
      bar = `Bar ${barStart / STEPS_PER_BAR + 1} of ${Math.ceil(this.preview.songSteps / STEPS_PER_BAR)}`;
    }
    const key = JSON.stringify([bar, cells]);
    if (key === this.gridKey) return;
    this.gridKey = key;
    this.setText('bar', bar);
    cells.forEach((cell, i) => {
      const item = this.gridCells[i];
      const [count, cue, owner, label] = [...item.children] as HTMLElement[];
      count.textContent = cell.count;
      cue.textContent = cell.text;
      owner.textContent = cell.chord;
      label.textContent = cell.label;
      item.dataset.kind = cell.kind;
      if (cell.current) item.setAttribute('aria-current', 'step'); else item.removeAttribute('aria-current');
    });
  }

  /** Chord chart with finger numbers; mirrored for left-handed players. */
  private renderBox(chord: ResolvedPlayerChord): void {
    const voicing = chord.voicing;
    const name = displayChordName(chord.chord);
    const rootPc = PITCH_CLASSES[chord.rootText];
    const names = this.tuning.map(string => displayNote(NOTE_NAMES[string.midi % 12]));
    const key = JSON.stringify([voicing?.frets ?? null, rootPc, name, names, this.look.hand]);
    if (key === this.boxKey) return;
    this.boxKey = key;
    const box = this.el('box');
    box.hidden = !voicing;
    box.innerHTML = this.chart(chord);
  }

  private chart(chord: ResolvedPlayerChord): string {
    return chord.voicing ? chordBoxSvg({
      frets: chord.voicing.frets, name: displayChordName(chord.chord), mirrored: this.look.hand === 'left',
      stringNames: this.tuning.map(string => displayNote(NOTE_NAMES[string.midi % 12])),
      roots: chord.voicing.frets.map((fret, s) => fret !== null && (this.tuning[s].midi + fret) % 12 === PITCH_CLASSES[chord.rootText]),
    }) : '';
  }

  private renderNeck(chord: ResolvedPlayerChord, step: PlayerPlan['steps'][number] | null, nextIndex: number | null): void {
    const voicing = chord.voicing;
    const sounding = new Set(step?.kind === 'play' ? step.notes.map(note => note.stringIndex) : []);
    const rootPc = PITCH_CLASSES[chord.rootText];
    const fingersMode = this.prefs.labels === 'fingers';
    const fingers = voicing && fingersMode ? suggestFingering(voicing.frets).fingers : null;
    const positions: ScaleNeckPosition[] = [];
    const spoken = new Map<number, string>();
    if (voicing) {
      for (const s of STRINGS) {
        const fret = voicing.frets[s];
        if (fret === null) continue;
        const note = this.toneLabel(chord, s, fret), finger = fingers?.[s];
        positions.push({
          stringIndex: s, fret, label: fingers ? (finger ? String(finger) : '') : note,
          role: (this.tuning[s].midi + fret) % 12 === rootPc ? 'root' : 'tone', active: sounding.has(s),
        });
        spoken.set(s, `${note}${finger ? `, ${FINGER_NAMES[finger as 1 | 2 | 3 | 4]} finger` : ''}`);
      }
    }
    const upcoming: Ghost[] = [];
    const ghostSpoken = new Map<number, string>();
    const target = nextIndex === null ? null : this.preview.chords[nextIndex];
    // Preview the next shape only as the change approaches: the last two beats, or the second half of a short chord.
    if (target?.voicing && step?.kind === 'play') {
      const remaining = chord.startStep + chord.steps - step.songStep;
      if (remaining <= Math.min(4, Math.ceil(chord.steps / 2))) {
        const nextFingers = fingersMode ? suggestFingering(target.voicing.frets).fingers : null;
        target.voicing.frets.forEach((fret, s) => {
          if (fret === null || positions.some(p => p.stringIndex === s && p.fret === fret)) return;
          const note = this.toneLabel(target, s, fret);
          upcoming.push({ stringIndex: s, fret, label: nextFingers ? (nextFingers[s] ? String(nextFingers[s]) : '') : note });
          ghostSpoken.set(s, note);
        });
      }
    }
    const stringLabels = this.tuning.map((string, s) => `${displayNote(NOTE_NAMES[string.midi % 12])}${voicing && voicing.frets[s] === null ? ' ×' : ''}`);
    this.neck.update({
      frets: voicing ? [...voicing.frets] : Array<number | null>(6).fill(null), tuning: this.tuning, stringLabels,
      root: chord.root, liveMidi: null, scalePositions: positions, upcoming,
    });
    this.flatCells.forEach((cell, i) => {
      const s = Math.floor(i / FRET_COUNT), f = i % FRET_COUNT;
      const position = positions.find(p => p.stringIndex === s && p.fret === f);
      const ghost = position ? undefined : upcoming.find(g => g.stringIndex === s && g.fret === f);
      const html = position
        ? `<span class="finger-dot${position.role === 'root' ? ' root-note' : ''}${position.active ? ' player-active' : ''}">${position.label}</span>`
        : ghost ? `<span class="finger-dot next-dot">${ghost.label}</span>` : '';
      if (html === this.cellHtml[i]) return;
      this.cellHtml[i] = html;
      cell.innerHTML = html;
      cell.disabled = !position;
      cell.setAttribute('aria-label', `String ${s + 1}, ${f === 0 ? 'open' : `fret ${f}`}${position
        ? `, ${spoken.get(s) ?? position.label}${position.role === 'root' ? ', root' : ''}${position.active ? ', sounding' : ''}`
        : ghost ? `, next chord ${ghostSpoken.get(s) ?? ghost.label}` : ''}`);
    });
    this.flatLabels.forEach((label, s) => { if (label.textContent !== stringLabels[s]) label.textContent = stringLabels[s]; });
    const name = displayChordName(chord.chord);
    this.renderCaption(chord);
    this.setText('summary', voicing
      ? `${chord.options.length} ${chord.options.length === 1 ? 'shape fits' : 'shapes fit'} this tuning. Switch to Build chords to compare shapes.`
      : `No shape for ${name} fits this tuning within fret ${PLAYER_LIMITS.maxFret}, so it stays silent. Try another root or type.`);
  }

  private renderCaption(chord: ResolvedPlayerChord): void {
    const status = this.stage?.getModelStatus();
    if (status?.preview) {
      this.setText('caption', `Original animation · ${status.clips.find(clip => clip.name === status.preview)!.label}`);
    } else {
      const name = displayChordName(chord.chord);
      this.setText('caption', chord.voicing ? `${name} · ${chord.voicing.name}` : `${name} · no shape`);
    }
  }

  private persist(): void {
    try {
      localStorage.setItem(PLAYER_STORAGE_KEY, serializePlayerStore(this.store));
      this.storageBlocked = false;
    } catch {
      this.storageBlocked = true;
    }
  }

  private get busy(): boolean { return Boolean(this.plan || this.pending); }

  /** Apply a new store; playback that was running restarts from the requested chord with the edited progression. */
  private commit(store: PlayerStore, options: CommitOptions = {}): void {
    const before = this.store;
    const current = this.displayIndex();
    const busy = this.busy;
    this.store = store;
    this.undoState = options.undo ? { store: before, selected: this.selected, label: options.undo } : null;
    if (options.selected !== undefined) this.selected = options.selected;
    this.persist();
    const restart = !busy || options.restart === undefined ? null
      : options.restart === 'selected' ? this.selected : options.restart === 'current' ? current : options.restart;
    if (restart !== null) this.halt();
    this.refresh();
    if (restart !== null) void this.play(Math.min(restart, this.preview.chords.length - 1), false, false);
  }

  private update(song: PlayerSong, options: CommitOptions = {}): boolean {
    try {
      this.commit({ ...this.store, current: validatePlayerSong(song) }, options);
      return true;
    } catch (error) {
      this.notice(errorText(error), true);
      this.refresh();
      return false;
    }
  }

  /** Keep an auto-generated name in step with the chords; a name the player typed is left alone. */
  private withChords(chords: PlayerChord[]): PlayerSong {
    const song = this.song;
    return { ...song, name: song.name === sequenceName(song.chords) ? sequenceName(chords) : song.name, chords };
  }

  private editSelected(change: { root?: string; quality?: ChordQuality; beats?: PlayerBeats; voicing?: string }, audition: boolean): void {
    const chord = this.preview.chords[this.selected];
    const original = this.song.chords[this.selected];
    if (!chord || !original) return;
    let edited: PlayerChord;
    try {
      if (change.root !== undefined || change.quality !== undefined) {
        edited = { chord: normalizeChordText(`${change.root ?? chord.rootText}${CHORD_QUALITY_DISPLAY[change.quality ?? chord.quality]}`), beats: original.beats };
      } else if (change.beats !== undefined) {
        edited = { ...original, beats: change.beats };
      } else {
        edited = change.voicing ? { ...original, voicing: change.voicing } : { chord: original.chord, beats: original.beats };
      }
    } catch (error) {
      this.notice(errorText(error), true);
      this.refresh();
      return;
    }
    const chords = this.song.chords.map((c, i) => i === this.selected ? edited : c);
    if (this.update(this.withChords(chords), { undo: 'edit', restart: 'selected' }) && audition && !this.busy) this.audition(this.selected);
  }

  private select(index: number): void {
    if (index < 0 || index >= this.preview.chords.length) return;
    this.selected = index;
    this.renderInspector();
    if (this.busy) void this.play(index, false, false);
    else { this.renderNow(); this.audition(index); }
  }

  private addChord(name?: string, duplicate = false): void {
    const chords = [...this.song.chords];
    if (chords.length >= PLAYER_LIMITS.maxChords) {
      this.notice(`A progression can hold up to ${PLAYER_LIMITS.maxChords} chords.`, true);
      return;
    }
    const at = this.selected + 1;
    const copy: PlayerChord = name ? { chord: name, beats: chords[this.selected].beats } : { ...chords[this.selected] };
    chords.splice(at, 0, copy);
    const current = this.displayIndex();
    if (this.update(this.withChords(chords), { undo: 'add', selected: at, restart: current >= at ? current + 1 : current })) {
      this.setMode('build');
      if (!name && !duplicate) this.el<HTMLSelectElement>('root').focus();
      this.notice(`${duplicate ? 'Duplicated' : 'Added'} ${displayChordName(copy.chord)} as chord ${at + 1}.${!name && !duplicate ? ' Choose its root and type in the editor.' : ''}`);
      if (name) this.audition(at);
    }
  }

  private move(delta: -1 | 1): void {
    const from = this.selected, to = from + delta;
    const chords = [...this.song.chords];
    if (to < 0 || to >= chords.length) return;
    [chords[from], chords[to]] = [chords[to], chords[from]];
    if (!this.update(this.withChords(chords), { undo: 'move', selected: to, restart: 'selected' })) return;
    this.notice(`Moved ${displayChordName(chords[to].chord)} to position ${to + 1}.`);
    const pressed = this.el<HTMLButtonElement>(delta < 0 ? 'earlier' : 'later');
    if (pressed.disabled) this.el<HTMLButtonElement>(delta < 0 ? 'later' : 'earlier').focus();
  }

  private removeSelected(): void {
    const chords = [...this.song.chords];
    if (chords.length <= 1) return;
    const [removed] = chords.splice(this.selected, 1);
    if (!this.update(this.withChords(chords), { undo: 'remove', selected: Math.min(this.selected, chords.length - 1), restart: 'selected' })) return;
    this.notice(`Removed ${displayChordName(removed.chord)}.`);
    if (this.el<HTMLButtonElement>('remove').disabled) this.el<HTMLButtonElement>('add').focus();
  }

  private usePreset(): void {
    const busy = this.busy;
    try {
      const song = presetSong(this.el<HTMLSelectElement>('preset').value, this.harmony.key, this.song);
      this.commit({ ...this.store, current: song }, { undo: 'progression', selected: 0, restart: 'selected' });
      this.notice(`Loaded ${song.name}.${busy ? '' : ' Open Chord player to hear it.'}`);
    } catch (error) {
      this.notice(errorText(error), true);
    }
  }

  private saveCurrent(): void {
    const input = this.el<HTMLInputElement>('save-name');
    try {
      const song = validatePlayerSong({ ...this.song, name: input.value });
      const result = saveSong(this.store, song);
      this.commit(result.store, result.replaced ? { undo: 'save' } : {});
      input.value = song.name;
      this.notice(this.storageBlocked ? `Kept “${song.name}” for this visit only; this browser is blocking saved data.`
        : result.replaced ? `Replaced the saved “${song.name}”.` : `Saved “${song.name}” in this browser.`);
    } catch (error) {
      this.notice(errorText(error), true);
    }
  }

  private loadSaved(): void {
    const name = this.el<HTMLSelectElement>('saved').value;
    const song = this.store.saved.find(candidate => candidate.name === name);
    if (!song) return;
    this.commit({ ...this.store, current: cloneSong(song) }, { undo: 'load', selected: 0, restart: 'selected' });
    this.notice(`Loaded “${song.name}”.`);
  }

  private deleteSaved(): void {
    const name = this.el<HTMLSelectElement>('saved').value;
    if (!this.store.saved.some(song => song.name === name)) return;
    this.commit(deleteSong(this.store, name), { undo: 'delete' });
    this.notice(`Deleted “${name}” from saved progressions.`);
  }

  private undo(): void {
    const state = this.undoState;
    if (!state) return;
    const restart = this.busy && musicKey(state.store.current) !== musicKey(this.store.current);
    if (restart) this.halt();
    this.undoState = null;
    this.store = state.store;
    this.selected = state.selected;
    this.persist();
    this.refresh();
    if (restart) void this.play(this.selected, false, false);
    this.notice('Restored.');
  }

  private setTempo(value: number, final: boolean): void {
    if (!Number.isFinite(value)) return;
    const bpm = Math.round(Math.min(PLAYER_LIMITS.maxBpm, Math.max(PLAYER_LIMITS.minBpm, value)));
    if (bpm !== this.song.bpm) {
      this.store = { ...this.store, current: { ...this.song, bpm } };
      this.undoState = null;
      this.renderSettings();
      if (this.busy) {
        window.clearTimeout(this.restartTimer);
        this.restartTimer = window.setTimeout(() => {
          this.restartTimer = 0;
          if (this.busy) void this.play(this.displayIndex(), false, false);
        }, 300);
      }
    }
    if (final) {
      this.persist();
      this.refresh();
    }
  }

  private async play(from: number, countIn: boolean, announce: boolean): Promise<void> {
    if (!this.active) return;
    let plan: PlayerPlan;
    try {
      plan = compilePlayerPlan(this.song, this.tuning, { from, countIn });
    } catch (error) {
      this.halt();
      this.status(errorText(error), true);
      this.renderNow();
      return;
    }
    this.halt();
    const generation = this.generation;
    const first = !this.audio;
    this.pending = true;
    if (first) this.status('Loading the recorded guitar…');
    this.renderNow();
    try {
      const audio = await this.actions.audio();
      if (generation !== this.generation) return;
      if (!this.active || document.hidden) {
        this.pending = false;
        this.renderNow();
        return;
      }
      this.audio = audio;
      this.pending = false;
      this.plan = plan;
      this.stepIndex = -1;
      this.transport.start(plan.entries, 0, plan.loop, plan.loopStart);
      if (announce || first) this.status(`Playing from ${displayChordName(plan.chords[plan.order[0]].chord)}${plan.loop ? ' · looping' : ''}.`);
      this.renderNow();
    } catch (error) {
      if (generation !== this.generation) return;
      this.halt();
      this.status(`Playback unavailable: ${errorText(error)}`, true);
      this.renderNow();
    }
  }

  /** Schedule one eighth-note step; the returned cancel silences only what this step started. */
  private playStep(index: number, at: number): () => void {
    const plan = this.plan, audio = this.audio;
    const step = plan?.steps[index];
    if (!plan || !audio || !step) return () => {};
    const started: AudioBufferSourceNode[] = [];
    let click: (() => void) | null = null;
    try {
      if (step.click) {
        click = playMetronomeClick(audio.context, step.click === 'accent', at);
        this.clicks.add(click);
      }
      for (const note of step.notes) {
        const source = this.sound(audio, note.stringIndex, note.fret, at + note.offset, note.ring, note.velocity);
        if (source) started.push(source);
      }
    } catch {
      // A note that fails to start must not stop the transport.
    }
    if (this.stage) {
      try {
        const current = this.stageStep(plan, index, at);
        const nextIndex = index + 1 < plan.steps.length ? index + 1 : plan.loop ? plan.loopStart : -1;
        if (current) this.stage.playStep(current, nextIndex < 0 ? null : this.stageStep(plan, nextIndex, at + plan.stepSeconds));
      } catch (error) {
        console.warn('The 3D hand animation could not follow the current step.', error);
        this.stage.stopPlayback();
        this.status('Hand animation paused for this step. Audio continues; use the 2D view for the selected shape.', true);
      }
    }
    return () => {
      if (click) { click(); this.clicks.delete(click); }
      started.forEach(source => this.fade(source));
    };
  }

  /** What the 3D hands do on one step: hold a shape, then strum, pluck or rest. Count-in steps show the first chord. */
  private stageStep(plan: PlayerPlan, index: number, at: number): StageStep | null {
    const step = plan.steps[index];
    if (!step) return null;
    const chord = plan.chords[step.chordIndex] ?? plan.chords[plan.order[0]];
    return {
      at, stepSeconds: plan.stepSeconds, frets: chord?.voicing?.frets ?? null, family: plan.pattern.family,
      stroke: STAGE_STROKES[step.cue.kind], stepInBar: step.stepInBar,
      notes: step.notes.map(note => ({ stringIndex: note.stringIndex, offset: note.offset })),
    };
  }

  private sound(audio: PlayerAudio, stringIndex: number, fret: number, start: number, ring: number, velocity: number): AudioBufferSourceNode | null {
    const string = this.tuning[stringIndex];
    if (!string) return null;
    const source = playAcousticString(audio.context, audio.bus, {
      freq: 440 * 2 ** ((string.midi + fret - 69) / 12), startTime: start, stringIndex, velocity, endTime: start + ring,
    });
    this.sources.set(source, start);
    source.addEventListener('ended', () => this.sources.delete(source), { once: true });
    return source;
  }

  /** Short fade instead of a hard stop so cancelled strings do not click. */
  private fade(source: AudioBufferSourceNode): void {
    const start = this.sources.get(source);
    if (start === undefined) return;
    this.sources.delete(source);
    const audio = this.audio;
    const gain = audio?.bus.sources.get(source);
    if (!audio || !gain) return;
    try {
      const now = audio.context.currentTime;
      if (start > now + .005) { source.stop(); return; }
      const level = gain.gain;
      if (typeof level.cancelAndHoldAtTime === 'function') level.cancelAndHoldAtTime(now);
      else {
        const value = level.value;
        level.cancelScheduledValues(now);
        level.setValueAtTime(value, now);
      }
      level.linearRampToValueAtTime(0, now + .012);
      source.stop(now + .015);
    } catch {
      // The string already finished.
    }
  }

  private halt(): void {
    this.generation++;
    this.pending = false;
    window.clearTimeout(this.restartTimer);
    this.restartTimer = 0;
    this.transport.stop();
    this.plan = null;
    this.stepIndex = -1;
    [...this.sources.keys()].forEach(source => this.fade(source));
    this.clicks.forEach(cancel => cancel());
    this.clicks.clear();
    this.stage?.stopPlayback();
  }

  private audition(index: number): void {
    const chord = this.preview.chords[index];
    if (!chord) return;
    const voicing = chord.voicing;
    if (!voicing) {
      this.notice(`${displayChordName(chord.chord)} has no playable shape in this tuning, so there is nothing to hear.`, true);
      return;
    }
    void this.withAudio(audio => {
      const start = audio.context.currentTime + .03;
      [...STRINGS].reverse().filter(s => voicing.frets[s] !== null).forEach((s, k) => {
        this.sound(audio, s, voicing.frets[s]!, start + k * .022, 1.8, .78 * (.85 + (5 - s) * .03));
      });
    });
  }

  private async withAudio(run: (audio: PlayerAudio) => void): Promise<void> {
    const busy = this.busy;
    this.halt();
    if (busy) {
      this.status('Stopped so you can hear the chord on its own.');
      this.renderNow();
    }
    const generation = this.generation;
    try {
      const audio = await this.actions.audio();
      if (generation !== this.generation || !this.active || document.hidden) return;
      this.audio = audio;
      run(audio);
    } catch (error) {
      if (generation === this.generation) this.notice(`Sound unavailable: ${errorText(error)}`, true);
    }
  }

  /** Clicking a marked fret plays that string; while playing it sounds over the progression without stopping it. */
  private pick(stringIndex: number, fret: number): void {
    const chord = this.preview.chords[this.displayIndex()];
    if (!chord?.voicing || chord.voicing.frets[stringIndex] !== fret) {
      this.status('Choose a marked fret to hear that string.');
      return;
    }
    if (this.plan && this.audio) {
      try { this.sound(this.audio, stringIndex, fret, this.audio.context.currentTime + .01, 1.6, .85); } catch { /* Best effort. */ }
      return;
    }
    const generation = this.generation;
    this.actions.audio().then(audio => {
      if (generation !== this.generation || !this.active) return;
      this.audio = audio;
      this.sound(audio, stringIndex, fret, audio.context.currentTime + .01, 1.6, .85);
    }).catch(error => {
      if (generation === this.generation) this.notice(`Sound unavailable: ${errorText(error)}`, true);
    });
  }

  /** Stop playback, any count-in and every string the player started. */
  stop(message = 'Stopped.'): void {
    const busy = this.busy || this.transport.running;
    this.halt();
    if (busy) {
      this.status(message);
      this.renderNow();
    }
  }

  setActive(active: boolean): void {
    if (!active && this.active) this.stop('Stopped because you left the Chord Library.');
    this.active = active;
    this.neck.setActive(active && this.mode === 'player');
  }

  setTuning(tuning: readonly StringTuning[], capo: number): void {
    const changed = capo !== this.capo || tuning.length !== this.tuning.length || tuning.some((string, i) => string.midi !== this.tuning[i].midi);
    if (!changed) return;
    this.stop('Stopped because the tuning or capo changed.');
    this.tuning = tuning.map(string => ({ ...string }));
    this.capo = capo;
    this.refresh();
  }

  dispose(): void {
    this.abort.abort();
    this.halt();
    this.neck.dispose();
  }
}
