export const PERCUSSION_LOOKAHEAD = .14;
export const PERCUSSION_TICK_MS = 25;

/** Retime only unscheduled steps; calculate from an anchor rather than accumulating timer delays. */
export class AudioStepClock {
  private anchorTime: number;
  private anchorStep = 0;
  private step = 0;

  constructor(startTime: number, private seconds: number) {
    if (!Number.isFinite(startTime) || startTime < 0) throw new Error('Invalid audio-clock start time.');
    this.validate(seconds);
    this.anchorTime = startTime;
  }

  private validate(seconds: number): void {
    if (!Number.isFinite(seconds) || seconds <= 0) throw new Error('Invalid audio-clock step duration.');
  }
  get nextTime(): number { return this.anchorTime + (this.step - this.anchorStep) * this.seconds; }
  get index(): number { return this.step; }
  advance(): void { this.step++; }
  retime(seconds: number): void {
    this.validate(seconds);
    if (seconds === this.seconds) return;
    this.anchorTime = this.nextTime; this.anchorStep = this.step; this.seconds = seconds;
  }
}

export function percussionRandom(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** The same small, seeded timing/dynamic variation used by Drum grooves. */
export function humanizePercussionHit(time: number, velocity: number, anchor: boolean, random: () => number): { time: number; velocity: number } {
  const timing = random() * 2 - 1, dynamics = random() * 2 - 1;
  return {
    time: time + timing * (anchor ? .003 : .006),
    velocity: Math.min(1, Math.max(.05, velocity * (1 + dynamics * .07))),
  };
}
