export function presetSong(progressionId: string, key: NoteName, base: PlayerSong): PlayerSong {
  const progression = PLAYER_PROGRESSIONS.find(candidate => candidate.id === progressionId);
  if (!progression) throw new Error('Choose one of the listed progressions.');
  const context = playerScaleContext(playerHarmony(key, progression.scale));
  const title = progression.legacy ? progression.label.replace(' (minor)', '') : progression.title;
  const name = `${title} in ${context.harmony.key}${progression.legacy && progression.scale === 'natural_minor' ? ' minor' : ''}`;
  const chords = progression.degrees.map((degree, index) => {
    const triad = context.chords[degree];
    const quality = progression.qualities?.[index];
    const chord = quality ? context.notes[degree].replaceAll('♯', '#').replaceAll('♭', 'b') + CHORD_QUALITY_DISPLAY[quality] : triad.chord;
    return { chord, beats: 4 };
  });
  return validatePlayerSong({ ...base, name, harmony: context.harmony, chords });
}

export function describeSong(song: PlayerSong): string {
  const beats = song.chords.reduce((sum, chord) => sum + chord.beats, 0);
  const seconds = Math.round(beats * 60 / song.bpm);
  const length = beats % 4 === 0 ? `${beats / 4} ${beats === 4 ? 'bar' : 'bars'}` : `${beats} ${beats === 1 ? 'beat' : 'beats'}`;
  return `${song.chords.length} ${song.chords.length === 1 ? 'chord' : 'chords'} · ${length} · ${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}
