/** Shared playing hand and skin tone; guitars retain their original materials. */

export type PlayingHand = 'right' | 'left';
export type SkinTone = 'light' | 'medium' | 'tan' | 'deep';

export interface GuitarLook {
  hand: PlayingHand;
  skin: SkinTone;
}

export const SKIN_TONES: Readonly<Record<SkinTone, { label: string; color: number; sheen: number; swatch: string }>> = {
  light: { label: 'Light', color: 0xf0c6a7, sheen: 0xffd9c4, swatch: '#f0c6a7' },
  medium: { label: 'Medium', color: 0xd59b74, sheen: 0xf2bf9c, swatch: '#d59b74' },
  tan: { label: 'Tan', color: 0xa86e47, sheen: 0xd79a72, swatch: '#a86e47' },
  deep: { label: 'Deep', color: 0x6b402a, sheen: 0xa86e4c, swatch: '#6b402a' },
};

export const GUITAR_LOOK_EVENT = 'gcs:guitar-look';
const STORAGE_KEY = 'gcs-guitar-look';
const DEFAULT_LOOK: GuitarLook = { hand: 'right', skin: 'medium' };
/** The look chosen this visit, so it still applies when storage is blocked. */
let chosen: GuitarLook | null = null;

function sanitize(value: unknown): GuitarLook {
  const raw = (value && typeof value === 'object' ? value : {}) as Partial<Record<keyof GuitarLook, unknown>>;
  return {
    hand: raw.hand === 'left' ? 'left' : 'right',
    skin: typeof raw.skin === 'string' && raw.skin in SKIN_TONES ? raw.skin as SkinTone : DEFAULT_LOOK.skin,
  };
}

export function getGuitarLook(): GuitarLook {
  if (chosen) return { ...chosen };
  try { return sanitize(JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null')); } catch { return { ...DEFAULT_LOOK }; }
}

/** Mirrors every 2D neck through CSS; 3D scenes and chord boxes read the look directly. */
export function applyGuitarLookToDocument(look: GuitarLook = getGuitarLook()): void {
  document.documentElement.dataset.guitarHand = look.hand;
}

export function setGuitarLook(patch: Partial<GuitarLook>): GuitarLook {
  const next = sanitize({ ...getGuitarLook(), ...patch });
  chosen = next;
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(next)); } catch { /* The look still applies for this visit. */ }
  applyGuitarLookToDocument(next);
  window.dispatchEvent(new CustomEvent<GuitarLook>(GUITAR_LOOK_EVENT, { detail: { ...next } }));
  return { ...next };
}

/** Subscribes to look changes from this tab and others; abort the signal to unsubscribe. */
export function onGuitarLookChange(listener: (look: GuitarLook) => void, signal: AbortSignal): void {
  window.addEventListener(GUITAR_LOOK_EVENT, event => listener({ ...(event as CustomEvent<GuitarLook>).detail }), { signal });
  window.addEventListener('storage', event => {
    if (event.key !== STORAGE_KEY) return;
    chosen = null;
    const look = getGuitarLook();
    applyGuitarLookToDocument(look);
    listener(look);
  }, { signal });
}
