import type { RhythmPreset, RhythmStroke } from '../tabs/rhythm';
import { isHandPercussionVoice, percussionHits, type PercussionHit, type PercussionKit } from './percussion';
import { AudioStepClock, humanizePercussionHit, percussionRandom } from './percussionTiming';

export interface PercussionSettings { bpm: number; humanize: boolean; seed: number }
export interface ScheduledPercussionHit extends PercussionHit { time: number; velocity: number }
export interface PercussionCue { time: number; step: number; cycle: number; stroke: RhythmStroke; hits: PercussionHit[] }

function validate(settings: PercussionSettings): void {
  if (!Number.isFinite(settings.bpm) || settings.bpm < 30 || settings.bpm > 260) throw new Error('Percussion tempo must be between 30 and 260 BPM.');
  if (typeof settings.humanize !== 'boolean' || !Number.isInteger(settings.seed)) throw new Error('Invalid percussion human-feel settings.');
}

/** One written pulse per tempo beat; human feel changes touch, not the pattern or the tempo grid. */
export class PercussionSequencer {
  private clock: AudioStepClock;
  private settings: PercussionSettings;
  private random: () => number;

  constructor(readonly preset: RhythmPreset, readonly kit: PercussionKit, settings: PercussionSettings, readonly startTime: number) {
    validate(settings);
    if (!preset.pattern.length || preset.pattern.length !== preset.beats) throw new Error('Invalid percussion pattern length.');
    for (const stroke of preset.pattern) {
      if (!Number.isFinite(stroke.vel) || stroke.vel <= 0 || stroke.vel > 1) throw new Error('Invalid percussion stroke velocity.');
      percussionHits(stroke.type, kit);
    }
    this.settings = { ...settings };
    this.clock = new AudioStepClock(startTime, 60 / settings.bpm);
    this.random = percussionRandom(settings.seed);
  }

  get nextTime(): number { return this.clock.nextTime; }
  update(changes: Partial<Omit<PercussionSettings, 'seed'>>): void {
    const next = { ...this.settings, ...changes };
    validate(next);
    this.settings = next;
    this.clock.retime(60 / next.bpm);
  }

  advance(until: number): { hits: ScheduledPercussionHit[]; cues: PercussionCue[] } {
    if (!Number.isFinite(until) || until < 0) throw new Error('Invalid percussion scheduling horizon.');
    const hits: ScheduledPercussionHit[] = [], cues: PercussionCue[] = [];
    for (let guard = 0; this.clock.nextTime < until; guard++) {
      if (guard >= 4096) throw new Error('Percussion scheduling fell too far behind.');
      const step = this.clock.index % this.preset.pattern.length, stroke = this.preset.pattern[step];
      const mapped = percussionHits(stroke.type, this.kit), gridTime = this.clock.nextTime;
      const expressive = this.settings.humanize && mapped.some(hit => isHandPercussionVoice(hit.voice));
      const touch = expressive
        ? humanizePercussionHit(gridTime, stroke.vel, !!stroke.sam || mapped.some(hit => hit.channel === 'bass'), this.random)
        : { time: gridTime, velocity: stroke.vel };
      const time = Math.max(this.startTime, touch.time);
      // A composite bol stays one coordinated two-hand stroke, not two independently jittered hits.
      for (const hit of mapped) hits.push({ ...hit, time, velocity: touch.velocity });
      cues.push({ time, step, cycle: Math.floor(this.clock.index / this.preset.pattern.length), stroke, hits: mapped });
      this.clock.advance();
    }
    return { hits, cues };
  }
}
